    ["You have changes that are not saved. Leave without saving?"] = "Vannak nem mentett módosításaid. Mentés nélkül kilépsz?",
    ["{count} of {max}"] = "{count} / {max}",
    ["Mature content"] = "Felnőtt tartalom",
    ["Local AI model"] = "Local AI modell",
    ["Uncensored model"] = "Cenzúrázatlan modell",
    ["No model installed"] = "Nincs telepített modell",
    ["another model"] = "egy másik modell",
    ["The Local AI model you chose is missing, does not fit in the free graphics memory or did not start, so {model} was used instead."] = "A kiválasztott Local AI-modell hiányzik, nem fér be a szabad grafikus memóriába, vagy nem indult el, ezért helyette ezt használtuk: {model}.",
    ["The Local AI model you chose needs about {need} MB of graphics memory, but only {available} MB are available for it beside the game, so {model} was used instead."] = "A kiválasztott Local AI-modellnek kb. {need} MB grafikus memóriára van szüksége, de a játék mellett csak {available} MB áll rendelkezésére, ezért helyette ezt használtuk: {model}.",
    ["Local AI switched to {model}: the game is using most of your graphics memory."] = "Local AI átváltott {model} modellre: a játék a videomemória nagy részét használja.",
    ["Choose one of the listed Local AI models."] = "Válassz egyet a felsorolt Local AI-modellek közül.",
    ["Characters to invite"] = "Meghívható karakterek",
    ["Whose memories"] = "Kinek az emlékei",
    ["Invalid Mature content settings."] = "Érvénytelen felnőtt tartalom beállítások.",
    ["Your message was not sent. Open the text box again and retype it."] = "Az üzeneted nem lett elküldve. Nyisd meg újra a szövegmezőt, és írd be még egyszer.",
    ["Not usable: {models}. See the Local AI notes, \"Add your own model\"."] = "Nem használható: {models}. Lásd a Local AI megjegyzéseit: „Saját modell hozzáadása“.",
    ["an embedding model, not a chat model"] = "beágyazó (embedding) modell, nem csevegőmodell",
    ["could not be read"] = "nem sikerült beolvasni",
    ["file not found"] = "a fájl nem található",
    ["not a valid GGUF file"] = "nem érvényes GGUF-fájl",
    ["{name} (custom)"] = "{name} (egyéni)",
    ["{name}: {reason}"] = "{name}: {reason}",
    ["Preparing {name}: waiting for the conversation service to connect…"] = "{name} előkészítése: várakozás a beszélgetési szolgáltatás csatlakozására…",
    ["Preparing {name}: waiting for the voice model to load…"] = "{name} előkészítése: várakozás a hangmodell betöltésére…",
    ["Preparing {name}: waiting for the conversation connection to open…"] = "{name} előkészítése: várakozás a beszélgetési kapcsolat megnyitására…",
    ["Preparing {name}: waiting for the game to place the character…"] = "{name} előkészítése: várakozás, amíg a játék elhelyezi a karaktert…",
    ["Preparing {name}: waiting for the memory service…"] = "{name} előkészítése: várakozás az emlékszolgáltatásra…",
    ["Preparing {count} more companions…"] = "További {count} társ előkészítése…",
    ["The conversation service did not answer. Wait a moment, then invite again."] = "A beszélgetési szolgáltatás nem válaszolt. Várj egy kicsit, majd hívd meg újra.",
    ["The voice model did not load. Check the voice in Settings or choose another one, then invite again."] = "A hangmodell nem töltődött be. Nézd meg a hangot a Beállításokban, vagy válassz másikat, majd hívd meg újra.",
    ["The memory service did not respond. Check your connection, then invite again."] = "Az emlékszolgáltatás nem válaszolt. Ellenőrizd a kapcsolatot, majd hívd meg újra.",
    ["The conversation connection did not open. Check your connection, then invite again."] = "A beszélgetési kapcsolat nem nyílt meg. Ellenőrizd a kapcsolatot, majd hívd meg újra.",
    ["Convai sign-in is busy right now. Wait a few minutes, then invite again."] = "A Convai bejelentkezése most foglalt. Várj pár percet, majd hívd meg újra.",
    ["The Convai daily limit is used up. Choose another provider in Settings, or invite again tomorrow."] = "A Convai napi kerete elfogyott. Válassz másik szolgáltatót a Beállításokban, vagy hívd meg újra holnap.",
    ["The Convai daily limit is used up. It resets at {time}. Choose another provider in Settings, or invite again then."] = "A Convai napi kerete elfogyott. Visszaáll {time}-kor. Válassz másik szolgáltatót a Beállításokban, vagy hívd meg akkor újra.",
    ["Calls are not available during combat."] = "Hívások harc közben nem elérhetők.",
    ["Calls are not available right now."] = "Most nem érhetők el a hívások.",
    ["Holocall ended: combat started."] = "A holohívás véget ért: harc kezdődött.",
    ["Holocall with {name} ended."] = "Véget ért a holohívás ({name}).",
    ["Live picture unavailable. The call continues with the portrait."] = "Az élő kép nem elérhető. A hívás a portréval folytatódik.",
    ["This contact cannot take a holocall."] = "Ez a névjegy nem fogadhat holohívást.",
    ["You are already on a call."] = "Már hívásban vagy.",
    ["A nearby companion makes one short comment as combat starts and another afterward.\n\nTen-minute cooldown after a fight. Conversations and story scenes come first. Loading a save resets the cooldown."] = "A közeli társ rövid megjegyzést tesz a harc kezdetén, és egy másikat utána.\n\nHarc után tíz perces szünet. A beszélgetések és a történetjelenetek élveznek elsőbbséget. Mentés betöltése nullázza a szünetet.",
    ["Ask a companion to drive to your selected map waypoint.\n\nGet into the passenger seat when they are ready."] = "Kérd meg a társat, hogy vezessen a kijelölt térképi ponthoz.\n\nAmikor készen állnak, ülj be az utasülésre.",
    ["Auto: follows the completed encounter in this save.\n\nCasual: speaks with that familiarity.\n\nOrdinary: keeps her usual manner.\n\nIt does not imply an ongoing relationship."] = "Automatikus: a mentésben lezárult találkozáshoz igazodik.\n\nLaza: ezzel a bizalmassággal beszél.\n\nHétköznapi: megtartja szokásos modorát.\n\nNem jelent tartós kapcsolatot.",
    ["Auto: follows the relationship in this save.\n\nRomantic: speaks to V as a partner.\n\nOrdinary: keeps their usual manner.\n\nOnly changes how they talk, never your game choices."] = "Automatikus: a mentésben lévő kapcsolathoz igazodik.\n\nRomantikus: V-hez partnerként szól.\n\nHétköznapi: megtartja szokásos modorát.\n\nCsak a beszédmódot változtatja, sosem a játékbeli döntéseidet.",
    ["Bluetooth audio arrives a little late, so lips and subtitles can run ahead of the voice. This holds them back to match, for every voice.\n\nAuto: 150 ms while Windows plays through Bluetooth, none otherwise. Pick a value if your headset is faster or slower.\n\nThe game’s own dialogue has the same delay and does not correct it."] = "A Bluetooth-hang kicsit később érkezik, így az ajak és a feliratok megelőzhetik a hangot. Ez a beállítás minden hangnál késlelteti őket, hogy szinkronban legyenek.\n\nAutomatikus: 150 ms, amíg a Windows Bluetoothon játszik, egyébként nincs. Adj meg értéket, ha a fejhallgatód gyorsabb vagy lassabb.\n\nA játék saját párbeszédei ugyanígy késnek, és a játék ezt nem korrigálja.",
    ["Chat history stays available across game launches.\n\nForgetting a character also clears their saved Chat messages and drafts. Forgetting all memories clears all saved chats."] = "A csevegési előzmények a játék indításai között is elérhetők maradnak.\n\nEgy karakter elfelejtése törli a mentett Csevegés-üzeneteit és piszkozatait is. A minden emlék elfelejtése minden mentett csevegést töröl.",
    ["Companions comment after you finish collecting loot from the world. Storage transfers stay silent.\n\nOrdinary comments are ten minutes apart; newly acquired Legendary gear has its own two-minute cooldown.\n\nPickups made during a fight are folded into one comment at its end."] = "A társak a világ zsákmányának összegyűjtése után kommentálnak. A tárolóba történő átvitelek néma maradnak.\n\nA szokásos megjegyzések között legalább tíz perc telik el; az újonnan szerzett legendás felszerelés saját két perces szünettel rendelkezik.\n\nHarc közben szerzett tárgyak a harc végén egy megjegyzésbe vannak összevonva.",
    ["Custom models are ones you added; they join the default choice by size."] = "Az egyéni modelleket te adtad hozzá; méret szerint az alapértelmezetthez csatlakoznak.",
    ["Eyes only: the head stays still and just the eyes move.\n\nSubtle to Strong: the head turns toward you more and more."] = "Csak szem: a fej mozdulatlan marad, csak a szemek mozognak.\n\nVisszafogottól Erősig: a fej egyre jobban feléd fordul.",
    ["Forget all memories applies to these characters.\n\nBrowsing the catalogue or inviting a companion does not add anyone to this count."] = "A minden emlék elfelejtése ezekre a karakterekre vonatkozik.\n\nA katalógus böngészése vagy társ meghívása nem ad hozzá senkit ehhez a számhoz.",
    ["Gang members, NCPD officers, guards, ripperdocs, shopkeepers, bartenders and passers-by answer as their kind of person.\n\nThey do not know your story and forget you after a save load, except shopkeepers you come back to.\n\nNamed characters are not affected."] = "A bandatagok, NCPD-tisztek, őrök, ripperdocok, boltosok, csaposok és járókelők a saját típusuk szerint válaszolnak.\n\nNem ismerik a történetedet, és mentés betöltése után elfelejtenek, kivéve azokat a boltosokat, akikhez visszatérsz.\n\nAz elnevezett karakterek nem érintettek.",
    ["Talk to story characters"] = "Beszélgetés történetbeli karakterekkel",
    ["{name} is busy right now."] = "{name} most elfoglalt.",
    ["{name} is not in your head right now."] = "{name} most nincs a fejedben.",
    ["{name} is a story character. Turn on Talk to story characters in Esc > Mods."] = "{name}: kapcsold be a „Beszélgetés történetbeli karakterekkel” opciót (Esc > Mods).",
    ["Talk to ordinary NPCs is off. Turn it on in Esc > Mods."] = "Beszélgetés hétköznapi NPC-kkel ki van kapcsolva. Kapcsold be az Esc > Mods-ban.",
    ["{name} is a child and cannot be talked to."] = "{name} gyermek, ezért vele nem lehet beszélgetni.",
    ["{name} is not a person and cannot be talked to."] = "{name} nem személy, ezért vele nem lehet beszélgetni.",
    ["{name} cannot be talked to: the mod cannot tell which voice fits."] = "{name}: vele nem lehet beszélgetni, mert a mod nem tudja, melyik hang illik.",
    ["If a character stops answering, voices stop or an error appears: choose Generate report and send the file it names to the developer, with a short note about what you were doing.\n\nThe logs listed below show what went wrong."] = "Ha egy karakter nem válaszol, a hangok leállnak vagy hiba jelenik meg: válaszd a Jelentés létrehozása opciót, és küldd el a fejlesztőnek a megnevezett fájlt, rövid megjegyzéssel arról, mit csináltál.\n\nAz alább felsorolt naplók mutatják, mi ment rosszul.",
    ["Invited characters are prepared immediately. Their memories start when you actually talk to them.\n\nOne player identity is shared across all saves and stays the same after forgetting.\n\nCurrent game context describes the world you have loaded."] = "A meghívott karakterek azonnal előkészítésre kerülnek. Emlékeik akkor indulnak, amikor valóban beszélsz velük.\n\nEgy játékosazonosító minden mentés között közös, és az elfelejtés után is ugyanaz marad.\n\nA jelenlegi játékkontextus a betöltött világot írja le.",
    ["Only Mature models found. Turn on Mature content to use them."] = "Csak felnőtt modellek találhatók. Kapcsold be a Felnőtt tartalmat.",
    ["Something on this PC (a firewall or security software) is blocking the connection to the model server you added."] = "Valami ezen a gépen (tűzfal vagy biztonsági szoftver) blokkolja a kapcsolatot a hozzáadott modellszerverrel.",
    ["Never allowed: sex with minors or without consent, sex about real people, hate, real-world weapon or drug instructions. A safety check enforces the minors rule."] = "Tilos: szex kiskorúval vagy beleegyezés nélkül, valódi személyekkel, gyűlölet, valós fegyver- vagy drogútmutató. Biztonsági ellenőrzés védi a kiskorúakat.",
    ["Off: replies are text only and no voice is generated.\n\nWith Subtitles off as well, automatic reactions stay silent."] = "Ki: a válaszok csak szövegesek, és nincs hanggenerálás.\n\nHa a Feliratok is ki vannak kapcsolva, az automatikus reakciók csendben maradnak.",
    ["See what each character remembers and make one or all of them forget.\n\nMemories are kept across saves."] = "Megnézheted, mit jegyez meg az egyes karakter, és egyet vagy mindegyiket elfelejtetheted.\n\nAz emlékek a mentések között megmaradnak.",
    ["Voxtral · not with Mature"] = "Voxtral · Felnőtt nélkül",
    ["Voxtral is not used with Mature content."] = "A Voxtral nem használható felnőtt tartalommal.",
    ["Needs Local AI or Custom."] = "Local AI vagy Egyéni szükséges.",
    ["Mature content is turned off because you chose a model that is not a Mature model."] = "A Felnőtt tartalom ki van kapcsolva, mert olyan modellt választottál, amely nem felnőtt modell.",
    ["Strong language, graphic violence, drugs and, between consenting adults, flirting and sex. Adults only (18+). Needs Local AI or Custom."] = "Erős nyelv, kegyetlen erőszak, drogok, beleegyező felnőttek közt flört és szex. Csak felnőtteknek (18+). Local AI vagy Egyéni szükséges.",
    ["Use it if companions seem to look above or below your eyes."] = "Használd, ha úgy tűnik, hogy a társak a szemed fölé vagy alá néznek.",
    ["Voxtral · Mistral cloud"] = "Voxtral · Mistral felhő",
    ["Voxtral · needs Mistral key"] = "Voxtral · Mistral-kulcs kell",
    ["{name} (custom · too large)"] = "{name} (egyéni · túl nagy)",
    ["{name} (custom, {size} GB, needs {need} GB)"] = "{name} (egyéni, {size} GB, {need} GB kell)",
    ["{name} (custom, {size} GB, too large for this card)"] = "{name} (egyéni, {size} GB, túl nagy ehhez a videokártyához)",
    ["Clear memories about you for every character you have talked to.\n\nYour player identity stays. A confirmation comes first."] = "Töröld a rólad szóló emlékeket minden karakternél, akivel beszéltél.\n\nA játékosazonosságod megmarad. Előbb megerősítést kell adnod.",
    ["Saves a report file you can send to the developer.\n\nAPI keys, tokens, IDs, microphone audio and conversation text are left out. Without the conversation service, a shorter report is made from the files the game can read."] = "Mentsd el a fejlesztőnek elküldhető jelentésfájlt.\n\nAz API-kulcsok, tokenek, azonosítók, mikrofonhang és beszélgetésszöveg kimaradnak. A beszélgetési szolgáltatás nélkül rövidebb jelentés készül a játék által olvasható fájlokból.",
    ["The Mature pack’s uncensored models (for Local AI) give the full effect; standard models mostly refuse sex. Pack: installed."] = "Cenzúrázatlan Mature-modellek (Local AI-hoz): teljes hatás; sima modellek többnyire nem vállalnak szexet. Csomag: telepítve.",
    ["The Mature pack’s uncensored models (for Local AI) give the full effect; standard models mostly refuse sex. Pack: not installed (optional, on this mod’s Hugging Face page)."] = "Cenzúrázatlan Mature-modellek (Local AI-hoz): teljes hatás; sima modellek többnyire nem vállalnak szexet. Csomag: nincs telepítve (opcionális, a mod Hugging Face-oldalán).",
    ["Until you choose one, Local AI loads the largest model that fits your free graphics memory.\n\nOne model at a time; a change applies when it next loads. A model that is missing, too large or failing is replaced by the largest that fits, with one notice."] = "Amíg nem választasz, a Local AI a szabad videomemóriába férő legnagyobb modellt tölti be.\n\nEgyszerre egy modell; a változás a következő betöltéskor lép életbe. A hiányzó, túl nagy vagy hibás modellt a legnagyobb befér modell váltja, egy értesítéssel.",
    ["Convai did not accept your API key. Check it in Settings > Conversation provider."] = "A Convai nem fogadta el az API-kulcsodat. Ellenőrizd a Beállítások > Beszélgetési szolgáltató menüpontban.",
    ["Local AI could not start. Check Local AI in Settings > Conversation provider."] = "A Local AI nem indult el. Nézd meg a Local AI-t a Beállítások > Beszélgetési szolgáltatónál.",
    ["Mistral did not accept your key. Check it in Settings > Conversation provider."] = "A Mistral nem fogadta el a kulcsodat. Ellenőrizd a Beállítások > Beszélgetési szolgáltató menüpontban.",
    ["Mistral has no key yet, so Convai is used. Add your key in Settings > Conversation provider."] = "A Mistral-hoz még nincs kulcs, ezért a Convai van használatban. Add meg a kulcsodat a Beállítások > Beszélgetési szolgáltató menüpontban.",
    ["Speaking to companions needs Convai for now. Set Conversation provider to Convai free tier in Settings > Conversation provider, or type your message."] = "A társakkal való beszélgetéshez egyelőre Convai kell. Állítsd a Beszélgetési szolgáltató értékét Convai (ingyenes szint) értékre a Beállítások > Beszélgetési szolgáltató menüpontban, vagy írd be az üzenetedet.",
    ["Your Convai API key has reached its plan limit. Try again later or add a different key in Settings > Conversation provider."] = "A Convai API-kulcsod elérte a tarifa keretét. Próbáld újra később, vagy adj meg másik kulcsot a Beállítások > Beszélgetési szolgáltató menüpontban.",
    ["Paste"] = "Beillesztés",
    ["no Omni pack"] = "nincs Omni-csomag",
    ["Add your Convai API key below to see and buy a plan."] = "Lent add meg a Convai API-kulcsodat, hogy lásd és megvásárolhass egy tarifát.",
    ["Add your Convai API key first."] = "Előbb add meg a Convai API-kulcsodat.",
    ["Add your Convai API key first: copy it, then choose Paste on the Convai API key row."] = "Előbb add meg a Convai API-kulcsodat: másold ki, majd a Convai API-kulcs sorban válaszd a Beillesztés lehetőséget.",
    ["Asking Convai for the payment page…"] = "Fizetési oldal lekérése a Convaitól…",
    ["Asks Convai which plan your key has now. After paying, it can take about 15 seconds."] = "A Convai most megkérdezi, milyen tarifa van most a kulcsodhoz. Fizetés után ez körülbelül 15 másodpercig tarthat.",
    ["Billed every month."] = "Havonta számlázva.",
    ["Billed once a year."] = "Évente egyszer számlázva.",
    ["Buy"] = "Vásárlás",
    ["Check"] = "Ellenőrzés",
    ["Check my plan"] = "Tarifám ellenőrzése",
    ["Checking your plan…"] = "Tarifa ellenőrzése…",
    ["Choose Check my plan to ask Convai."] = "Válaszd a Tarifám ellenőrzése lehetőséget, hogy megkérdezd a Convaitól.",
    ["Contacting Convai…"] = "Kapcsolódás a Convaihoz…",
    ["Convai could not start the payment. Try again later."] = "A Convai nem tudta elindítani a fizetést. Próbáld újra később.",
    ["Convai did not accept your API key."] = "A Convai nem fogadta el az API-kulcsodat.",
    ["Convai does not show a paid plan for your key yet."] = "A Convai ehhez a kulcshoz még nem mutat fizetős tarifát.",
    ["Convai has not confirmed your plan yet. Check it in Settings > Convai paid tier."] = "A Convai még nem erősítette meg a tarifádat. Ellenőrizd a Beállítások > Convai fizetős szint menüpontban.",
    ["Convai paid tier"] = "Convai fizetős szint",
    ["Convai’s payment page is open in your browser. Your plan is active about 15 seconds after you pay."] = "A Convai fizetési oldala megnyílt a böngésződben. A tarifád fizetés után körülbelül 15 másodperccel aktiválódik.",
    ["Convai’s payment service did not answer. Try again in a moment."] = "A Convai fizetési szolgáltatása nem válaszolt. Próbáld újra kis idő múlva.",
    ["Convai’s plans for this mod: more Convai conversations on your own Convai API key. Opens a page with the plans and their prices."] = "A Convai tarifái ehhez a modhoz: több Convai-beszélgetés a saját Convai API-kulcsoddal. Megnyit egy oldalt a tarifákkal és árakkal.",
    ["Conversations with Convai API key chosen as the provider use this plan."] = "Ha a szolgáltatónak a Convai API-kulcs van kiválasztva, a beszélgetések ezt a tarifát használják.",
    ["Get your Convai API key"] = "Szerezd meg a Convai API-kulcsodat",
    ["Manage or cancel plan"] = "Tarifa kezelése vagy lemondása",
    ["Free"] = "Ingyenes",
    ["Gamer, monthly"] = "Gamer, havi",
    ["Gamer, yearly"] = "Gamer, éves",
    ["Gamer Pro, monthly"] = "Gamer Pro, havi",
    ["Gamer Pro, yearly"] = "Gamer Pro, éves",
    ["Current plan"] = "Jelenlegi tarifa",
    ["This is your current plan. To change or cancel it, choose Manage or cancel plan below."] = "Ez a jelenlegi tarifád. A módosításhoz vagy lemondáshoz válaszd lent a Tarifa kezelése vagy lemondása lehetőséget.",
    ["No key added"] = "Nincs kulcs megadva",
    ["Not checked yet"] = "Még nincs ellenőrizve",
    ["Opened in your browser."] = "Megnyitva a böngészőben.",
    ["Opening the page in your browser…"] = "Az oldal megnyitása a böngészőben…",
    ["Opens Convai’s payment page (Stripe) in your browser. You pay Convai directly; the mod never sees your card. Your plan is active about 15 seconds after you pay, and conversations then use your Convai API key."] = "Megnyitja a Convai fizetési oldalát (Stripe) a böngészőben. A fizetést közvetlenül a Convainak küldöd; a mod soha nem látja a kártyádat. A tarifád körülbelül 15 másodperccel a fizetés után aktiválódik, a beszélgetések pedig ezután a Convai API-kulcsodat használják.",
    ["Opens convai.com in your browser. Sign in or make a free account, copy your API key, then come back and choose Paste below."] = "Megnyitja a convai.com oldalt a böngészőben. Jelentkezz be, vagy hozz létre ingyenes fiókot, másold ki az API-kulcsodat, majd térj vissza, és lent válaszd a Beillesztés lehetőséget.",
    ["Opens your Convai billing page in your browser. Sign in with the same Convai account to change or cancel your plan."] = "Megnyitja a Convai számlázási oldaladat a böngészőben. A tarifa módosításához vagy lemondásához jelentkezz be ugyanazzal a Convai-fiókkal.",
    ["Plans"] = "Tarifák",
    ["Plans Convai made for this mod. They give your own Convai API key more conversations; the free tier stays as it is."] = "A Convai által ehhez a modhoz készített tarifák. Ezek több beszélgetést adnak a saját Convai API-kulcsodhoz; az ingyenes szint változatlan marad.",
    ["Prices in US dollars. You can cancel at any time on Convai’s billing page."] = "Árak amerikai dollárban. Bármikor lemondhatod a Convai számlázási oldalán.",
    ["The conversation service is not running, so plans cannot be shown. Restart the game."] = "A beszélgetési szolgáltatás nem fut, ezért a tarifák nem jeleníthetők meg. Indítsd újra a játékot.",
    ["This key has no paid plan. Choose a plan below."] = "Ehhez a kulcshoz nincs fizetős tarifa. Válassz lent egyet.",
    ["Your Convai plan"] = "A Convai-tarifád",
    ["Your Convai plan is active."] = "A Convai-tarifád aktív.",
    ["Your Convai plan is active. Choose Convai API key in Settings > Conversation provider."] = "A Convai-tarifád aktív. Válaszd a Convai API-kulcs lehetőséget a Beállítások > Beszélgetési szolgáltató menüpontban.",
    ["Your Convai plan is active. Conversations now use your Convai API key."] = "A Convai-tarifád aktív. A beszélgetések mostantól a Convai API-kulcsodat használják.",
    ["Your browser could not be opened."] = "A böngészőt nem sikerült megnyitni.",
    ["Your plan could not be read right now. Try again in a moment."] = "A tarifádat most nem sikerült beolvasni. Próbáld újra kis idő múlva.",
    ["{count} Convai interactions a month."] = "{count} Convai-interakció havonta.",
    ["{plan}, {price} a month"] = "{plan}, {price} havonta",
    ["{plan}, {price} a year"] = "{plan}, {price} évente",
    ["Sign in with Convai"] = "Bejelentkezés Convai-val",
    ["Sign in"] = "Bejelentkezés",
    ["Opens Convai’s sign-in page in your browser.\n\nSign in or make a free account, and your Convai API key is saved on this computer, the same as Paste. You have five minutes."] = "Megnyitja a Convai bejelentkezési oldalát a böngészőben.\n\nJelentkezz be, vagy hozz létre ingyenes fiókot, a Convai API-kulcsod pedig ezen a számítógépen kerül mentésre, ugyanúgy, mint a Beillesztés esetén. Öt perced van.",
    ["Opening Convai’s sign-in page in your browser…"] = "A Convai bejelentkezési oldalának megnyitása a böngészőben…",
    ["Sign in on the Convai page in your browser. Your key is saved here when you finish."] = "Jelentkezz be a Convai oldalán a böngészőben. A kulcsod itt kerül mentésre, amikor végeztél.",
    ["Signed in. Your Convai API key is saved."] = "Sikeres bejelentkezés. A Convai API-kulcsod mentve.",
    ["The sign-in took too long. Choose Sign in with Convai to try again."] = "A bejelentkezés túl sokáig tartott. Válaszd a Bejelentkezés Convai-val lehetőséget az újrapróbálkozáshoz.",
    ["The sign-in did not finish. Try again, or copy your key from convai.com and choose Paste."] = "A bejelentkezés nem fejeződött be. Próbáld újra, vagy másold ki a kulcsodat a convai.com oldalról, és válaszd a Beillesztés lehetőséget.",
    ["Choose one of the listed voices for V."] = "Válassz a felsorolt hangok közül egyet V-nek.",
    ["Pocket · On your PC"] = "Pocket · A gépeden",
    ["Johnny in your head"] = "Johnny a fejedben",
    ["Johnny in your head is off. Turn it on in Settings > Conversations."] = "A Johnny a fejedben ki van kapcsolva. Kapcsold be a Beállítások > Beszélgetések menüpontban.",
    ["Choose how often Johnny speaks up."] = "Válaszd ki, milyen gyakran szólal meg Johnny.",
    ["A clip you add replaces the shipped voice of this character for Pocket, OmniVoice and the Voxtral cloud voice."] = "A hozzáadott klip felülírja ennek a karakternek az eredeti hangját a Pocket, az OmniVoice és a Voxtral felhőhang számára.",
    ["A display name is too long. Keep each one under {max} characters."] = "Egy megjelenítendő név túl hosszú. Mindegyik legyen {max} karakter alatt.",
    ["A new or removed clip counts from the next line this character speaks, once the current reply is over. Nothing needs restarting."] = "Az új vagy eltávolított klip a karakter következő mondatától érvényes, amint a jelenlegi válasz véget ért. Semmit nem kell újraindítani.",
    ["A record name can only use letters, digits, dots, dashes and underscores, for example Character.Rebecca."] = "A rekordnév csak betűket, számjegyeket, pontokat, kötőjeleket és aláhúzásokat tartalmazhat, például Character.Rebecca.",
    ["Add a display name"] = "Megjelenítendő név hozzáadása",
    ["Add a record name"] = "Rekordnév hozzáadása",
    ["Add a record name or a display name, so the game can find this character."] = "Adj meg egy rekordnevet vagy egy megjelenítendő nevet, hogy a játék meg tudja találni ezt a karaktert.",
    ["Add voice clip"] = "Hangklip hozzáadása",
    ["Another character of yours, {other}, already answers to this record or name."] = "Egy másik karaktered, {other}, már erre a rekordra vagy névre válaszol.",
    ["Choose a gender"] = "Válassz nemet",
    ["Choose a gender."] = "Válassz nemet.",
    ["Chosen file: {name} ({size}). It is checked when you save it."] = "Kiválasztott fájl: {name} ({size}). Mentéskor ellenőrzésre kerül.",
    ["Chosen file: {name}, {seconds} seconds."] = "Kiválasztott fájl: {name}, {seconds} másodperc.",
    ["Clip removed."] = "A klip eltávolítva.",
    ["Delete character"] = "Karakter törlése",
    ["Delete {name}? The character, its voice clip and what it remembers of you are removed."] = "Törlöd {name} karaktert? A karakter, a hangklipje és minden, amit rólad megjegyzett, törlődik.",
    ["Display names"] = "Megjelenítendő nevek",
    ["Female"] = "Nő",
    ["Filled in from the character you were facing: {name}."] = "Kitöltve a karakter alapján, akivel szemben álltál: {name}.",
    ["For example: Character.Rebecca"] = "Például: Character.Rebecca",
    ["For example: Rebecca"] = "Például: Rebecca",
    ["Gender"] = "Nem",
    ["Give the character a name."] = "Adj nevet a karakternek.",
    ["How the game finds this character"] = "Hogyan találja meg a játék ezt a karaktert",
    ["It picks the voice when the character has no clip."] = "Ha a karakternek nincs klipje, a neme határozza meg a hangot.",
    ["Male"] = "Férfi",
    ["Memories"] = "Emlékek",
    ["Name"] = "Név",
    ["New character"] = "Új karakter",
    ["No clip yet."] = "Még nincs klip.",
    ["Optional. Pocket, OmniVoice and the Voxtral cloud voice copy a clip you add. Without one the character speaks with a generic voice that fits the gender."] = "Opcionális. A Pocket, az OmniVoice és a Voxtral felhőhang másolja a hozzáadott klipet. Klip nélkül a karakter a nemének megfelelő általános hangon beszél.",
    ["Play saved clip"] = "Mentett klip lejátszása",
    ["Record names"] = "Rekordnevek",
    ["Remove clip"] = "Klip eltávolítása",
    ["Remove the voice clip? The character goes back to a generic voice."] = "Eltávolítod a hangklipet? A karakter visszatér az általános hangra.",
    ["Remove the voice clip? {name} goes back to the shipped voice."] = "Eltávolítod a hangklipet? {name} visszatér az eredeti hangjára.",
    ["Save clip"] = "Klip mentése",
    ["Save the character first. Then it can have a voice clip, and it starts to remember your talks."] = "Először mentsd el a karaktert. Utána kaphat hangklipet, és elkezdi megjegyezni a veled folytatott beszélgetéseket.",
    ["Saved clip: {seconds} seconds."] = "Mentett klip: {seconds} másodperc.",
    ["Saved. The clip is a little long: 10 to 18 seconds copies best."] = "Mentve. A klip kissé hosszú: a 10–18 másodperces klipek másolódnak a legjobban.",
    ["Saved. The clip is a little short: 10 to 18 seconds copies best."] = "Mentve. A klip kissé rövid: a 10–18 másodperces klipek másolódnak a legjobban.",
    ["That file is not a recording the voices can read. Use a WAV, MP3, OGG or FLAC file."] = "A fájl nem olyan felvétel, amelyet a hangok olvasni tudnak. Használj WAV, MP3, OGG vagy FLAC fájlt.",
    ["That file is too big for a voice clip."] = "Ez a fájl túl nagy egy hangklipnek.",
    ["The clip is mostly silence. Use a clip where somebody is talking most of the time."] = "A klip szinte teljesen csend. Használj olyan klipet, amelyben a legtöbb időben valaki beszél.",
    ["The clip is too long. Use at most {max} seconds."] = "A klip túl hosszú. Legfeljebb {max} másodperc lehet.",
    ["The clip is too short. Use at least {min} seconds."] = "A klip túl rövid. Legalább {min} másodperc kell.",
    ["The game did not name anyone. Face the character, then choose Settings > Edit characters > Open in the game again."] = "A játék senkit sem nevezett meg. Nézz a karakter felé, majd a játékban válaszd újra a Beállítások > Karakterek szerkesztése > Megnyitás lehetőséget.",
    ["The game recognises the person you talk to by a record name, a display name, or both. A record name looks like Character.Rebecca or NCA.Rebecca. Add at least one."] = "A játék a rekordnév, a megjelenítendő név vagy mindkettő alapján ismeri fel azt, akivel beszélsz. A rekordnév így néz ki: Character.Rebecca vagy NCA.Rebecca. Adj meg legalább egyet.",
    ["The name is too long. Keep it under {max} characters."] = "A név túl hosszú. Tartsd {max} karakter alatt.",
    ["The name of the character’s record in the game files."] = "A karakter rekordjának neve a játék fájljaiban.",
    ["The name the character goes by. They give it when somebody asks who they are."] = "A név, amelyen a karakter ismert. Akkor mondja ki, amikor valaki megkérdezi, ki ő.",
    ["The name the game shows for the character."] = "A név, amelyet a játék a karakterhez mutat.",
    ["The recording is distorted. Record it again, a little quieter."] = "A felvétel torz. Vedd fel újra, kicsit halkabban.",
    ["The recording is too low in quality. Use at least {min} Hz."] = "A felvétel minősége túl alacsony. Legalább {min} Hz kell.",
    ["The recording is too quiet to copy. Record it louder, or closer to the microphone."] = "A felvétel túl halk a másoláshoz. Vedd fel hangosabban, vagy közelebb a mikrofonhoz.",
    ["The saved clip could not be loaded."] = "A mentett klipet nem sikerült betölteni.",
    ["The words said in the clip are too long. Keep them under {max} characters."] = "A klipben elmondott szavak túl hosszúak. Tartsd {max} karakter alatt.",
    ["This character speaks with a generic voice that fits the gender."] = "Ez a karakter a nemének megfelelő általános hangon beszél.",
    ["This character speaks with the shipped voice."] = "Ez a karakter az eredeti hangján beszél.",
    ["This computer cannot convert that file. Save it as a WAV and try again."] = "Ez a számítógép nem tudja átalakítani ezt a fájlt. Mentsd el WAV-ként, és próbáld újra.",
    ["Too many display names. Keep {max} or fewer."] = "Túl sok megjelenítendő név. Legfeljebb {max} maradhat.",
    ["Too many record names. Keep {max} or fewer."] = "Túl sok rekordnév. Legfeljebb {max} maradhat.",
    ["Type the words said in the clip, at least {min} characters."] = "Írd be a klipben elhangzott szavakat, legalább {min} karakter hosszan.",
    ["Type what the clip says, as spoken. OmniVoice needs it to copy the voice."] = "Írd le, amit a klip mond, úgy, ahogy elhangzik. Az OmniVoice-nak erre van szüksége a hang másolásához.",
    ["Use the character I’m facing"] = "A szemben lévő karakter használata",
    ["Use {min} to {max} seconds of one person speaking clearly, with no music or other voices. {goodMin} to {goodMax} seconds copies best. WAV, MP3, OGG or FLAC."] = "Használj {min}–{max} másodperc hosszú felvételt egy tisztán beszélő személytől, zene és más hangok nélkül. A {goodMin}–{goodMax} másodperces klipek másolódnak a legjobban. WAV, MP3, OGG vagy FLAC.",
    ["Voice"] = "Hang",
    ["Who this character is, what they know and how they look. Writing it as “I am …” works best. A long bio makes replies slower, so keep it tight."] = "Ki ez a karakter, mit tud és hogyan néz ki. A legjobb „Én vagyok …” formában írni. A hosszú életrajz lassítja a válaszokat, ezért tartsd tömörre.",
    ["Words said in the clip"] = "A klipben elhangzott szavak",
    ["You have as many voice clips as the editor keeps ({max}). Remove one first."] = "Már annyi hangklipod van, amennyit a szerkesztő megtart ({max}). Előbb törölj egyet.",
    ["You have made as many characters as the editor keeps ({max}). Delete one first."] = "Annyi karaktert hoztál létre, amennyit a szerkesztő megtart ({max}). Először törölj egyet.",
    ["Your character"] = "A karaktered",
    ["Your characters"] = "A karaktereid",
    ["{other} already has a profile in the mod, and that profile always wins. Use another record or name."] = "{other} már rendelkezik profillal a modban, és ez a profil mindig elsőbbséget élvez. Használj másik rekordot vagy nevet.",
    ["A pack is one folder too deep. See Help in Settings."] = "Csomag egy mappával mélyebb. Súgó a Beállításokban.",
    ["All files found."] = "Minden fájl megtalálva.",
    ["Browser"] = "Böngésző",
    ["Found."] = "Megtalálva.",
    ["Found: {list}."] = "Megtalálva: {list}.",
    ["Game version"] = "Játékverzió",
    ["Graphics card"] = "Videokártya",
    ["Internet"] = "Internet",
    ["Loaded."] = "Betöltve.",
    ["Local AI could not start. Generate a report below and send it, or choose another conversation provider."] = "A Local AI nem tudott elindulni. Alul hozz létre egy jelentést, és küldd el, vagy válassz másik beszélgetési szolgáltatót.",
    ["Local AI found no graphics card it can use. It needs an NVIDIA or AMD card with a current driver. Update the driver, or choose another conversation provider."] = "A Local AI nem talált használható videokártyát. NVIDIA vagy AMD kártya kell hozzá, friss illesztőprogrammal. Frissítsd az illesztőprogramot, vagy válassz másik beszélgetési szolgáltatót.",
    ["Missing: {files}. Extract the Scripts zip into the Cyberpunk 2077 folder again and let it replace the files."] = "Hiányzik: {files}. Csomagold ki újra a Scripts zip-et a Cyberpunk 2077 mappába, és engedd felülírni a fájlokat.",
    ["Mod files"] = "Modfájlok",
    ["Mod manager"] = "Modkezelő",
    ["Moved into place from {folder}: {packs}."] = "Áthelyezve innen: {folder}: {packs}.",
    ["No Local AI pack found. Download one from the mod’s Hugging Face page and extract it into the Cyberpunk 2077 folder, or choose another conversation provider."] = "Nincs Local AI-csomag. Tölts le egyet a mod Hugging Face oldaláról, és csomagold ki a Cyberpunk 2077 mappába, vagy válassz másik beszélgetési szolgáltatót.",
    ["No problem found. Select a line to see what was checked."] = "Nem találtunk problémát. Válassz ki egy sort, és nézd meg, mit ellenőriztünk.",
    ["No sign of the conversation service in this session: the Runtime is missing or did not load. Extract the full install zip (AI-NPC-LLM-Companions) straight into the Cyberpunk 2077 folder (not into a new folder), check that red4ext/plugins/AiNpcCyberpunkMod is there, then restart the game. The full install is on the mod’s Nexus Mods page."] = "Ebben a munkamenetben nincs nyoma a beszélgetési szolgáltatásnak: a Runtime hiányzik, vagy nem töltődött be. Csomagold ki a teljes telepítő zip-et (AI-NPC-LLM-Companions) közvetlenül a Cyberpunk 2077 mappába (ne új mappába), ellenőrizd, hogy ott van a red4ext/plugins/AiNpcCyberpunkMod, majd indítsd újra a játékot. A teljes telepítő a mod Nexus Mods oldalán található.",
    ["None found: installed by hand."] = "Nincs találat: kézzel telepítve.",
    ["None installed. They are optional."] = "Nincs telepítve. Opcionálisak.",
    ["Not needed: Local AI and the voice run on this PC."] = "Nem szükséges: a Local AI és a hang ezen a gépen fut.",
    ["Not used"] = "Nincs használatban",
    ["Not your conversation provider. Choose it in Settings > Conversation provider."] = "Ez nincs beállítva beszélgetési szolgáltatóként. Válaszd ki a Beállítások > Beszélgetési szolgáltató menüpontban.",
    ["Note"] = "Megjegyzés",
    ["OK"] = "OK",
    ["Optional packs"] = "Opcionális csomagok",
    ["Problem"] = "Probléma",
    ["Problems found: {count}. Select a line marked Problem to read what to do."] = "Talált problémák: {count}. Válaszd ki a Probléma jelzésű sort, és olvasd el, mit kell tenni.",
    ["RED4ext is not loaded. Install it from Nexus Mods, then restart the game. It also starts the conversation service."] = "A RED4ext nincs betöltve. Telepítsd a Nexus Modsról, majd indítsd újra a játékot. Emellett elindítja a beszélgetési szolgáltatást.",
    ["Reached {host}."] = "{host} elérhető.",
    ["Scripts and Runtime"] = "Scripts és Runtime",
    ["Scripts {scripts} and Runtime {runtime}."] = "Scripts {scripts} és Runtime {runtime}.",
    ["Scripts {scripts} on Runtime base {runtime}."] = "Scripts {scripts} Runtime-alapon {runtime}.",
    ["These Scripts {scripts} need the Runtime base {required} or newer, and your Runtime is {runtime}. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Ezek a Scripts {scripts} a Runtime-alap {required} vagy újabb verzióját igénylik, a te Runtime-od pedig {runtime}. Csomagold ki a teljes telepítő zip-et (AI-NPC-LLM-Companions, a Nexus Mods oldalán) a Cyberpunk 2077 mappába, majd indítsd újra a játékot.",
    ["The Runtime is older than {required}. Get the full install zip."] = "A Runtime régebbi, mint {required}. Töltsd le a teljes ZIP-et.",
    ["Setup check"] = "Telepítés-ellenőrzés",
    ["Some mod files are missing. Extract the update zip again. See Help in Settings."] = "Hiányzó modfájlok. Bontsd ki újra az update ZIP-et. Lásd: Súgó a Beállításokban.",
    ["Some pack files could not be moved into place because different files are already there. Extract the pack into the Cyberpunk 2077 folder again and let it replace the files."] = "Néhány csomagfájlt nem lehetett áthelyezni, mert más fájlok már ott vannak. Csomagold ki újra a csomagot a Cyberpunk 2077 mappába, és engedd felülírni a fájlokat.",
    ["The Runtime is incomplete ({code}). Extract the full install zip (AI-NPC-LLM-Companions) into the Cyberpunk 2077 folder again and let it replace the files, then restart the game."] = "A Runtime hiányos ({code}). Csomagold ki újra a teljes telepítő zip-et (AI-NPC-LLM-Companions) a Cyberpunk 2077 mappába, és engedd, hogy felülírja a fájlokat, majd indítsd újra a játékot.",
    ["The settings file of the launcher, launcher.ini, is missing from red4ext/plugins/AiNpcCyberpunkMod, so the game cannot start the conversation service. Extract the full install zip (AI-NPC-LLM-Companions) straight into the Cyberpunk 2077 folder again (by hand, also with Vortex) and let it replace the files, then restart the game."] = "Az indító beállításfájlja, a launcher.ini hiányzik a red4ext/plugins/AiNpcCyberpunkMod mappából, ezért a játék nem tudja elindítani a beszélgetési szolgáltatást. Csomagold ki újra a teljes telepítő zip-et (AI-NPC-LLM-Companions) közvetlenül a Cyberpunk 2077 mappába (kézzel, Vortex esetén is), és engedd, hogy felülírja a fájlokat, majd indítsd újra a játékot.",
    ["The conversation service cannot reach the internet. See Help in Settings."] = "A beszélgetési szolgáltatás nem ér el internetet. Lásd: Súgó a Beállításokban.",
    ["The conversation service cannot reach {host}. Allow Node.js through your firewall or antivirus (Windows asks once; choose Allow), check your internet, then restart the game."] = "A beszélgetési szolgáltatás nem éri el ezt: {host}. Engedélyezd a Node.js-t a tűzfalon vagy a vírusirtón (a Windows egyszer rákérdez; válaszd a Hozzáférés engedélyezése lehetőséget), ellenőrizd az internetet, majd indítsd újra a játékot.",
    ["The conversation service could not start ({code}). Restart the game. If it happens again, generate a report below and send it."] = "A beszélgetési szolgáltatás nem tudott elindulni ({code}). Indítsd újra a játékot. Ha ismétlődik, hozz létre alul egy jelentést, és küldd el.",
    ["The conversation service did not start. Is the Runtime installed? See Help in Settings."] = "A beszélgetési szolgáltatás nem indult el. Runtime telepítve? Lásd: Súgó a Beállításokban.",
    ["The game version could not be read."] = "A játék verzióját nem sikerült beolvasni.",
    ["This PC cannot look up {host}. Check your internet connection, then restart the game."] = "Ez a gép nem találja ezt: {host}. Ellenőrizd az internetkapcsolatot, majd indítsd újra a játékot.",
    ["Open r6/logs/redscript_rCURRENT.log. A mod it names is why the scripts did not load."] = "Nézd meg: r6/logs/redscript_rCURRENT.log. Az ott említett mod blokkolja a szkripteket.",
    ["This mod’s scripts did not load. Open r6/logs/redscript_rCURRENT.log. If the error names another mod, that mod is the problem. Missing or old Codeware or redscript, or a game version other than {game}, can also cause it."] = "Ennek a modnak a szkriptjei nem töltődtek be. Nyisd meg az r6/logs/redscript_rCURRENT.log fájlt. Ha a hiba egy másik modot nevez meg, az a mod a probléma. Okozhatja a Codeware vagy a redscript hiánya vagy régi verziója, illetve a {game}-től eltérő játékverzió is.",
    ["Missing: {names}. Install them and restart the game."] = "Hiányzik: {names}. Telepítsd őket, majd indítsd újra a játékot.",
    ["Install or update: {names}. Then restart the game."] = "Telepítsd vagy frissítsd: {names}. Utána indítsd újra a játékot.",
    ["Codeware is too old. Update it from Nexus Mods, then restart the game."] = "A Codeware túl régi. Frissítsd a Nexus Modsról, majd indítsd újra a játékot.",
    ["Version {version}."] = "Verzió: {version}.",
    ["Version {version}. The mod is tested on {game} only, so some things may not work."] = "Verzió: {version}. A mod csak a {game}-en van tesztelve, ezért előfordulhat, hogy egyes dolgok nem működnek.",
    ["Version {version}. These files are the mod build for game {build}. Extract the full install zip made for game {game}, from the mod’s Nexus Mods page, into the Cyberpunk 2077 folder, then restart the game."] = "Verzió: {version}. Ezek a fájlok a mod {build} verziójú játékhoz készült buildjei. Csomagold ki a {game} verziójú játékhoz készült teljes telepítő zip-et a mod Nexus Mods oldaláról a Cyberpunk 2077 mappába, majd indítsd újra a játékot.",
    ["Vortex. Install the optional packs by hand into the Cyberpunk 2077 folder, as the install steps say. Install the full install zip as one mod and update that mod with each new full install zip."] = "Vortex. A telepítési lépésekben leírtak szerint telepítsd kézzel az opcionális csomagokat a Cyberpunk 2077 mappába. A teljes telepítő zip-et egy modként telepítsd, és minden új teljes telepítő zip-pel frissítsd ezt a modot.",
    ["{name} is missing. Install it from Nexus Mods, then restart the game."] = "Hiányzik: {name}. Telepítsd a Nexus Modsról, majd indítsd újra a játékot.",
    ["{name}, {memory} GB of video memory."] = "{name}, {memory} GB videomemória.",
    ["{packs} is one folder too deep, in {folder}. Restart the game and the mod moves it into place. If it is still there afterwards, move the red4ext folder inside it into the Cyberpunk 2077 folder."] = "A(z) {packs} egy mappával mélyebben van, itt: {folder}. Indítsd újra a játékot, és a mod a helyére teszi. Ha utána is ott marad, helyezd át a benne lévő red4ext mappát a Cyberpunk 2077 mappába.",
    ["Add an endpoint URL and a model ID first."] = "Előbb add meg az endpoint URL-t és a modellazonosítót.",
    ["Convai: the custom provider is not set up yet"] = "Convai: az egyéni szolgáltató még nincs beállítva",
    ["Copy the base URL from your provider, for example https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 or http://localhost:11434/v1 (Ollama). It is read from the clipboard once and saved on this computer.\n\nOnly this computer and your home network may use http://. You can also fill in endpoint=, model= and api-key= in player-custom-endpoint.txt in the conversation service folder.\n\nNothing is sent until you choose this provider or press Test connection."] = "Másold ki a szolgáltatód alap URL-jét, például https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 vagy http://localhost:11434/v1 (Ollama). A vágólapról egyszer olvassuk be, és csak ezen a számítógépen mentjük.\n\nA http:// csak ezen a számítógépen és a házi hálózaton használható. Az endpoint=, model= és api-key= értékeket a player-custom-endpoint.txt fájlba is beírhatod a beszélgetési szolgáltatás mappájában.\n\nSemmi nem megy el, amíg ezt a szolgáltatót nem választod, vagy meg nem nyomod a Kapcsolat tesztje gombot.",
    ["Copy the model ID from your provider first, for example meta-llama/llama-3.1-8b-instruct on OpenRouter or llama3.2 on Ollama. It is read from the clipboard once and saved on this computer."] = "Előbb másold ki a modellazonosítót a szolgáltatódtól, például meta-llama/llama-3.1-8b-instruct (OpenRouter) vagy llama3.2 (Ollama). A vágólapról egyszer olvassuk be, és ezen a számítógépen mentjük.",
    ["Copy your API key from your provider first. It is read from the clipboard once and saved on this computer only. A server on your own computer, such as Ollama or LM Studio, usually needs no key."] = "Előbb másold ki az API-kulcsodat a szolgáltatódtól. A vágólapról egyszer olvassuk be, és csak ezen a számítógépen mentjük. Saját gépen futó szerverhez, például Ollama vagy LM Studio, általában nincs szükség kulcsra.",
    ["Custom (OpenAI-compatible)"] = "Egyéni (OpenAI-compatible)",
    ["Custom API key"] = "Egyéni API-kulcs",
    ["Custom endpoint URL"] = "Egyéni endpoint URL",
    ["Custom model ID"] = "Egyéni modellazonosító",
    ["Custom provider replies are spoken by a local voice instead of the Convai cloud voice."] = "Az egyéni szolgáltató válaszait helyi hang mondja, nem a Convai felhőhangja.",
    ["Custom: key not accepted"] = "Egyéni: a kulcs nem elfogadott",
    ["Custom: model unavailable"] = "Egyéni: a modell nem elérhető",
    ["Custom: out of credits"] = "Egyéni: elfogytak a kreditek",
    ["Custom: rate limited for now"] = "Egyéni: egyelőre korlátozva",
    ["Deletes the saved endpoint URL. The custom provider needs one to answer."] = "Törli a mentett endpoint URL-t. Az egyéni szolgáltatónak válaszoláshoz kell.",
    ["Deletes the saved key. Replies from the custom provider are then asked for without a key."] = "Törli a mentett kulcsot. Ezután az egyéni szolgáltatótól kulcs nélkül kérnek válaszokat.",
    ["Deletes the saved model ID. The custom provider needs one to answer."] = "Törli a mentett modellazonosítót. Az egyéni szolgáltatónak válaszoláshoz kell.",
    ["Failed"] = "Hiba",
    ["It answered in {ms} ms."] = "{ms} ms alatt válaszolt.",
    ["It could not be saved."] = "Nem sikerült menteni.",
    ["Model ID: {model}"] = "Modellazonosító: {model}",
    ["Only https:// works outside this computer and your home network."] = "Ezen a gépen és a házi hálózaton kívül csak https:// működik.",
    ["Paste API key"] = "Kulcs beillesztése",
    ["Paste endpoint URL"] = "URL beillesztése",
    ["Paste model ID"] = "ID beillesztése",
    ["Sends one tiny message to your endpoint with the saved model ID and key, and shows how it answered. It uses next to nothing of your credits."] = "Egy apró üzenetet küld az endpointra a mentett modell-azonosítóval és kulccsal, majd megmutatja a választ. Alig fogyaszt kreditet.",
    ["Test"] = "Teszt",
    ["Test connection"] = "Kapcsolat tesztje",
    ["Testing the connection…"] = "Kapcsolat tesztelése…",
    ["Testing…"] = "Tesztelés…",
    ["That is too long."] = "Ez túl hosszú.",
    ["That was not accepted."] = "Nem lett elfogadva.",
    ["The account is out of credits. Add credits with your provider."] = "Elfogytak a kreditek a fiókban. Tölts fel a szolgáltatódnál.",
    ["The address must start with https:// or http://."] = "A címnek https:// vagy http:// kezdetűnek kell lennie.",
    ["The address sends you somewhere else. Use the final address from your provider."] = "A cím máshová visz. Használd a szolgáltatódtól kapott végső címet.",
    ["That address is a web page, not the API. For OpenRouter use https://openrouter.ai/api/v1."] = "Ez a cím weboldal, nem az API. OpenRouterhez a https://openrouter.ai/api/v1 címet használd.",
    ["That address is a web page, not the API. Use the API address from your provider."] = "Ez a cím weboldal, nem az API. Használd a szolgáltatódtól kapott API-címet.",
    ["A model ID is a short name like that, not a web address."] = "A modellazonosító egy ilyen rövid név, nem webcím.",
    ["The clipboard does not hold a model ID."] = "A vágólapon nincs modellazonosító.",
    ["The clipboard does not hold a web address."] = "A vágólapon nincs webcím.",
    ["The clipboard does not hold an API key."] = "A vágólapon nincs API-kulcs.",
    ["The clipboard is empty. Copy it first."] = "A vágólap üres. Előbb másold ki.",
    ["The connection test failed."] = "A kapcsolatteszt sikertelen volt.",
    ["The connection works. The endpoint accepted your model and key."] = "A kapcsolat működik. Az endpoint elfogadta a modelledet és a kulcsodat.",
    ["The conversation service is not running, so nothing can be tested. Restart the game."] = "A beszélgetési szolgáltatás nem fut, ezért nincs mit tesztelni. Indítsd újra a játékot.",
    ["The custom provider did not accept your key. Check it in Settings > Conversation provider."] = "Az egyéni szolgáltató elutasította a kulcsot. Lásd: Beállítások > Beszélgetési szolgáltató.",
    ["The custom provider did not answer. Check its address in Settings, or try again."] = "Az egyéni szolgáltató nem válaszolt. Ellenőrizd a címét, vagy próbáld újra.",
    ["The custom provider does not know that model ID. Check it in Settings."] = "Az egyéni szolgáltató nem ismeri ezt a modellazonosítót. Ellenőrizd a Beállításokban.",
    ["The custom provider is not set up, so Convai is used. Add its URL and model ID in Settings."] = "Nincs egyéni szolgáltató: Convai válaszol. Add meg URL-t és modellazonosítót a Beállításokban.",
    ["The custom provider is rate limiting you. Try again in a moment."] = "Az egyéni szolgáltató korlátozza a kéréseidet. Próbáld újra kis idő múlva.",
    ["The custom provider says your account is out of credits. Add credits there, then try again."] = "Az egyéni szolgáltatónál elfogyott a kredit. Tölts fel, aztán próbáld újra.",
    ["The endpoint URL was removed."] = "Az endpoint URL törölve lett.",
    ["The endpoint answered with no text. Check the model ID."] = "Az endpoint szöveg nélkül válaszolt. Ellenőrizd a modellazonosítót.",
    ["The endpoint did not accept your API key."] = "Az endpoint nem fogadta el az API-kulcsodat.",
    ["The endpoint did not answer. Check its address."] = "Az endpoint nem válaszolt. Ellenőrizd a címét.",
    ["The endpoint does not know that model ID."] = "Az endpoint nem ismeri ezt a modellazonosítót.",
    ["The endpoint is rate limiting you. Try again in a moment."] = "Az endpoint korlátozza a kéréseidet. Próbáld újra kis idő múlva.",
    ["The endpoint is rate limiting you. Wait about {seconds} seconds, then try again."] = "Az endpoint korlátozza a kéréseidet. Várj kb. {seconds} másodpercet, aztán próbáld újra.",
    ["The endpoint refused the request. Check the model ID and the address."] = "Az endpoint elutasította a kérést. Ellenőrizd a modellazonosítót és a címet.",
    ["The endpoint reported an error on its side. Try again in a moment."] = "Az endpoint hibát jelzett a saját oldalán. Próbáld újra kis idő múlva.",
    ["The endpoint took too long to answer."] = "Az endpoint túl sokáig válaszolt.",
    ["The model ID was removed."] = "A modellazonosító törölve lett.",
    ["The provider said: {detail}"] = "A szolgáltató ezt mondta: {detail}",
    ["This address is not encrypted, which is fine on your own computer or home network."] = "Ez a cím nem titkosított, ami a saját gépeden vagy a házi hálózatodon rendben van.",
    ["Use the base URL only: no password, query or #."] = "Csak az alap URL-t add meg: jelszó, lekérdezés vagy # nélkül.",
    ["Waiting for the endpoint to answer…"] = "Várakozás az endpoint válaszára…",
    ["Custom: free daily limit reached"] = "Egyéni: elfogyott az ingyenes napi keret",
    ["New address saved. Paste your API key again for it."] = "Új cím elmentve. Illeszd be hozzá újra az API-kulcsot.",
    ["The free daily limit for this model was reached. It resets at {time}."] = "Ennek a modellnek elfogyott az ingyenes napi kerete. Visszaáll {time}-kor.",
    ["The free daily limit for this model was reached. Try again after it resets."] = "Ennek a modellnek elfogyott az ingyenes napi kerete. Próbáld újra a visszaállás után.",
    ["This model spends its reply on thinking. Choose a non-reasoning model in Settings."] = "A modell a válasz helyett gondolkodik. Válassz nem gondolkodó modellt a Beállításokban.",
    ["All"] = "Mind",
    ["Also changed: {names}."] = "Emellett módosítva: {names}.",
    ["Choose any character from the list below. They do not need to be in your current party."] = "Válassz bármelyik karaktert az alábbi listából. Nem kell a jelenlegi csapatodban lenniük.",
    ["Defaults restored."] = "Alapértelmezett értékek visszaállítva.",
    ["Drag the slider, or press left and right, to turn the page."] = "Húzd a csúszkát, vagy az oldal lapozásához nyomd meg a bal és a jobb nyilat.",
    ["How loud the mod’s voices are, for companions, characters and V’s typed lines. 100 is the normal level.\n\nAbove 100 the voices get louder, with a limiter so they do not crackle. The game’s own dialogue and sounds do not change.\n\nThe next reply uses it."] = "Mennyire hangosak a mod hangjai a társaknál, a szereplőknél és a V által begépelt soroknál. A 100 a normál szint.\n\n100 felett hangosabbak a hangok, limiterrel, hogy ne recsegjenek. A játék saját párbeszédei és hangjai nem változnak.\n\nA következő válasz használja.",
    ["Not available right now."] = "Jelenleg nem elérhető.",
    ["Open Settings to restore its defaults."] = "Nyisd meg a Beállításokat az alapértelmezett értékek visszaállításához.",
    ["Page"] = "Oldal",
    ["Show only the models whose name starts with this letter."] = "Csak azokat a modelleket mutatja, amelyek neve ezzel a betűvel kezdődik.",
    ["Starts with"] = "Kezdőbetű",
    ["Open AI NPC Cyberpunk Mod in the Mods list."] = "Nyisd meg az AI NPC Cyberpunk Mod-ot a Mods listájában.",
    ["The settings could not be saved. Nothing was changed."] = "A beállításokat nem sikerült menteni. Semmi nem változott.",
    ["Privacy"] = "Adatvédelem",
    ["Send error reports automatically"] = "Hibajelentések automatikus küldése",
    ["Error reports go to the developer automatically. Turn them off in Settings > Privacy."] = "Hibajelentések automatikusan a fejlesztőhöz mennek. Kikapcsolás: Beállítások > Adatvédelem.",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI"] = "A Társkezelőnek a Mod Configuration Menu 0.10.5 vagy újabb, vagy a Native Settings UI kell",
    ["Update Mod Configuration Menu to 0.10.5 or newer, or install Native Settings UI"] = "Frissítsd a Mod Configuration Menu-t 0.10.5 vagy újabbra, vagy telepítsd a Native Settings UI-t",
    ["Stand up to open the Companion Manager"] = "Állj fel a Társkezelő megnyitásához",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI {nsui} or newer. Either one is enough. Install one from Nexus Mods, then restart the game."] = "A Társkezelőnek a Mod Configuration Menu 0.10.5 vagy újabb, illetve a Native Settings UI {nsui} vagy újabb verziója kell. Bármelyik elég. Telepítsd valamelyiket a Nexus Modsról, majd indítsd újra a játékot.",
    ["Mod Configuration Menu is too old. Update it to 0.10.5 or newer, or install Native Settings UI, then restart the game."] = "A Mod Configuration Menu túl régi. Frissítsd 0.10.5 vagy újabb verzióra, vagy telepítsd a Native Settings UI-t, majd indítsd újra a játékot.",
    ["Previous page"] = "Előző oldal",
    ["Next page"] = "Következő oldal",
    ["Starts with: {letter}"] = "Kezdőbetű: {letter}",
    ["Characters and party"] = "Karakterek és csapat",
    ["Load a save first"] = "Előbb tölts be mentést",
    ["Inviting characters and managing your party need a loaded game."] = "A karakterek meghívásához és a csapat kezeléséhez betöltött játék kell.",
    ["Voxtral (recommended)"] = "Voxtral (ajánlott)",
    ["Defaults"] = "Gyári",
    ["Press Confirm to put every setting back to its default."] = "Nyomd meg a Megerősítés gombot, hogy minden beállítás visszakerüljön az alapértelmezett értékére.",
    ["Local AI stopped working and was restarted."] = "A Local AI leállt, és újra lett indítva.",
    ["Local AI runs mostly on your processor here, so replies will be slow."] = "A Local AI itt főleg a processzoron fut, ezért a válaszok lassúak lesznek.",
    ["Local AI is back on your graphics card, so replies are faster again."] = "A Local AI ismét a videokártyádon fut, ezért a válaszok megint gyorsabbak.",
    ["Voice files"] = "Hangfájlok",
    ["The voice files are incomplete. Reinstall the Full download from Nexus Mods."] = "A hangfájlok hiányosak. Telepítsd újra a teljes telepítő zip-et a Nexus Mods oldalról.",
    ["The voice files are incomplete, so the voices and the microphone cannot start. Reinstall the Full download from Nexus Mods: extract it into the Cyberpunk 2077 folder and let it replace the files, then restart the game."] = "A hangfájlok hiányosak, ezért a hangok és a mikrofon nem tudnak elindulni. Telepítsd újra a teljes telepítő zip-et a Nexus Mods oldalról: csomagold ki a Cyberpunk 2077 mappába, és engedd, hogy felülírja a fájlokat, majd indítsd újra a játékot.",
    ["Changes this mod’s menus and notices only.\n\nCharacter voices and the language you talk in are separate. The microphone uses this language as a hint for non-English speech."] = "Csak ennek a modnak a menüit és értesítéseit módosítja.\n\nA karakterek hangja és a nyelv, amelyen beszélsz, külön van kezelve. A mikrofon ezt a nyelvet tippként használja a nem angol beszédhez.",
    ["Deletes the saved key."] = "Törli a mentett kulcsot.",
    ["The Convai cloud voice cannot use Natural speech, so it was turned off."] = "A Convai felhőhang nem használhatja a természetes beszédet, ezért kikapcsoltuk.",
    ["Custom endpoint"] = "Egyéni endpoint",
    ["Speaks up often"] = "Gyakran megszólal",
    ["Speaks up rarely"] = "Ritkán megszólal",
    ["The address, API key and model ID of your OpenAI-compatible provider, and a connection test. Used when Custom is the Conversation provider."] = "Az OpenAI-kompatibilis szolgáltatód címe, API-kulcsa és modell-azonosítója, valamint egy kapcsolatteszt. Akkor használjuk, ha az Egyéni a beszélgetési szolgáltató.",
    ["OmniVoice · needs Omni pack"] = "OmniVoice · Omni-csomag kell",
    ["OmniVoice · needs Omni voice"] = "OmniVoice · Omni-hang kell",
    ["Requires the Companion voices to be an OmniVoice choice"] = "A társhangoknak OmniVoice-hangnak kell lenniük",
    ["V’s voice switches from OmniVoice to Pocket."] = "V hangja az OmniVoice-ról a Pocketre vált.",
    ["V’s voice"] = "V hangja",
    ["V (male voice)"] = "V (férfihang)",
    ["V (female voice)"] = "V (női hang)",
    ["Used for V’s typed lines: Pocket, OmniVoice and the Voxtral cloud voice copy it."] = "V begépelt soraihoz használják: a Pocket, az OmniVoice és a Voxtral felhőhang másolja.",
    ["V speaks with the voice of your installed V voice mod, or the shipped V voice."] = "V a telepített V-hangmod hangján vagy az eredeti V-hangon szólal meg.",
    ["Remove the voice clip? V goes back to the voice of your installed V voice mod, or the shipped V voice."] = "Eltávolítod a hangklipet? V visszatér a telepített V-hangmod hangjához, vagy az eredeti V-hanghoz.",
    ["OmniVoice needs an NVIDIA graphics card, and this PC has none that works. Replies show as text. Choose Pocket in Settings to hear voices."] = "Az OmniVoice NVIDIA videokártyát igényel, és ezen a gépen nincs működő. A válaszok szövegként jelennek meg. A hangokhoz a Beállításokban válaszd a Pocketet.",
    ["OmniVoice needs an NVIDIA graphics card, and this PC has none that works. Companions are using {voice} instead."] = "Az OmniVoice NVIDIA videokártyát igényel, és ezen a gépen nincs működő. A társak helyette {voice} hangot használnak.",
    ["OmniVoice needs NVIDIA"] = "OmniVoice NVIDIA-t igényel",
    ["This PC has no NVIDIA graphics card, which OmniVoice needs. OmniVoice will not start here. Choose Pocket to hear voices."] = "Ezen a gépen nincs NVIDIA videokártya, pedig az OmniVoice-nak szüksége van rá. Az OmniVoice itt nem indul el. A hangokhoz válaszd a Pocketet.",
    ["{voice} · needs NVIDIA card"] = "{voice} · NVIDIA-kártya kell",
    ["{language} replies show as text: the {language} multilingual pack is missing."] = "A {language} nyelvű válaszok szövegként jelennek meg: hiányzik a {language} többnyelvű csomag.",
    ["French"] = "francia",
    ["Italian"] = "olasz",
    ["German"] = "német",
    ["Spanish"] = "spanyol",
    ["Portuguese"] = "portugál",
    ["OmniVoice needs more graphics memory than is free next to the game. Pocket is used."] = "Az OmniVoice-hoz a játék mellett kevés a videomemória. Helyette Pocket fut.",
    ["Windows ran out of memory for the voice. A larger paging file or closing other apps helps."] = "A Windows memóriája elfogyott a hanghoz. Segít a nagyobb lapozófájl vagy programok bezárása.",
    ["OmniVoice needs 12 GB"] = "OmniVoice 12 GB-ot igényel",
    ["{voice} · needs 12 GB card"] = "{voice} · 12 GB-os kártya kell",
    ["The graphics card in this PC has less than the 12 GB OmniVoice needs next to the game. If it cannot start, Pocket is used. Choose Pocket to skip the wait."] = "Ezen a gépen a videokártya a játék mellett kevesebb, mint az OmniVoice-hoz szükséges 12 GB. Ha nem tud elindulni, Pocket lesz használva. A várakozás elkerüléséhez válaszd a Pocketet.",
    ["Forget all memories ({count} characters)"] = "Minden emlék elfelejtése ({count} karakter)",
    ["Dynamic info"] = "Élő információk",
    ["Location"] = "Helyszín",
    ["Where V is: the district, and V’s apartment or the named place when the game says so.\n\nOff: characters are not told where you are, and the mod stops reading it from the game. The picture Convai gets of what V sees, and an add-on’s own text, are not affected."] = "Hol van V: a kerület, V lakása, illetve a megnevezett hely, ha a játék ezt közli.\n\nKikapcsolva: a karakterek nem tudják, hol vagy, és a mod nem olvassa ki ezt a játékból. A Convai által kapott kép arról, amit V lát, és egy bővítmény saját szövege nem érintett.",
    ["Time and weather"] = "Idő és időjárás",
    ["The hour of the day and the weather in Night City.\n\nOff: nobody is told the time or the weather, and the mod stops reading them from the game."] = "A napszak és az időjárás Night City-ben.\n\nKikapcsolva: senki nem tudja meg az időt és az időjárást, és a mod nem olvassa ki ezeket a játékból.",
    ["Company and vehicle"] = "Társaság és jármű",
    ["Who else is with V, whether V is on foot or in a vehicle, and what a companion is doing beside V.\n\nOff: none of this is sent, and the mod stops reading it from the game."] = "Kivel van együtt V, hogy V gyalog van-e vagy járműben, és mit csinál a mellette lévő társ.\n\nKikapcsolva: ezek közül semmi nem kerül továbbításra, és a mod nem olvassa ki a játékból.",
    ["Health, heat and fights"] = "Egészség, körözés és harc",
    ["V’s health, the police heat on V, and the last fight V was in.\n\nOff: none of this is sent, and the mod stops reading it from the game."] = "V egészsége, a rendőrség körözési szintje V-n, és V utolsó harca.\n\nKikapcsolva: ezek közül semmi nem kerül továbbításra, és a mod nem olvassa ki a játékból.",
    ["V’s money"] = "V pénze",
    ["A rough idea of how many eddies V has: nearly broke, short, comfortable or rich.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "Nagyjából mennyi eddies van V-nél: szinte csőd, szűkösen, kényelmesen vagy gazdagon.\n\nKikapcsolva: nem kerül továbbításra, és a mod nem olvassa ki a játékból.",
    ["V’s gear and clothes"] = "V felszerelése és ruhái",
    ["What V wears and carries: clothes, weapons and cyberware that can be seen.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "Amit V visel és hord: a látható ruhák, fegyverek és cyberware.\n\nKikapcsolva: nem kerül továbbításra, és a mod nem olvassa ki a játékból.",
    ["V’s gender and lifepath"] = "V neme és életútja",
    ["Whether V is a woman or a man, and V’s lifepath: Nomad, Street Kid or Corpo.\n\nOff: it is not sent with a turn, and the mod stops reading it for that. Your story’s own facts may still reflect your lifepath."] = "Hogy V nő-e vagy férfi, és V életútja: Nomád, Utcagyerek vagy Corpo.\n\nKikapcsolva: a fordulókkal nem kerül továbbításra, és a mod ezért nem olvassa ki a játékból. A történet saját tényei továbbra is tükrözhetik az életutat.",
    ["Quest and journal"] = "Küldetés és napló",
    ["V’s tracked quest and its objectives, the jobs V has open and the journal history.\n\nWhat each character knows about your story stays on.\n\nOff: none of this is sent. The mod stops scanning the journal for it, unless Johnny’s remarks are on."] = "V követett küldetése és annak célkitűzései, V nyitott munkái és a napló előzményei.\n\nAz egyes karakterek tudása a történetedről bekapcsolva marad.\n\nKikapcsolva: ezek közül semmi nem kerül továbbításra, és a mod nem olvassa be a naplót, kivéve ha Johnny megjegyzései be vannak kapcsolva.",
    ["Recent game dialogue"] = "Legutóbbi játékbeli párbeszéd",
    ["The last lines spoken in scenes and V’s chosen replies, so a character can pick up from what was just said.\n\nOff: they are not sent."] = "A jelenetekben utoljára elhangzott sorok és V választott válaszai, hogy a karakter onnan folytathassa, ahol az előbb abbamaradt.\n\nKikapcsolva: nem kerülnek elküldésre.",
    ["The Runtime is out of date. Get the full install zip."] = "A Runtime elavult. Töltsd le a teljes telepítő zip-et.",
    ["The Scripts and Runtime do not match. Update whichever is older. See Help in Settings."] = "A Scripts és a Runtime nem egyeznek. Frissítsd a régebbit. Lásd a Súgót a Beállításokban.",
    ["Scripts {scripts} and Runtime {runtime} do not match: the Runtime is out of date. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "A Scripts {scripts} és a Runtime {runtime} nem egyeznek: a Runtime elavult. Csomagold ki a teljes telepítő zip-et (AI-NPC-LLM-Companions, a Nexus Mods oldalán) a Cyberpunk 2077 mappába, majd indítsd újra a játékot.",
    ["Scripts {scripts} and Runtime {runtime} do not match. If the Scripts are older, install the update zip from Nexus Mods. If the Runtime is older, install the full install zip (AI-NPC-LLM-Companions). Extract into the Cyberpunk 2077 folder, then restart the game."] = "A Scripts {scripts} és a Runtime {runtime} nem egyeznek. Ha a Scripts a régebbi, telepítsd a frissítő zip-et a Nexus Modsról. Ha a Runtime a régebbi, telepítsd a teljes telepítő zip-et (AI-NPC-LLM-Companions). Csomagold ki a Cyberpunk 2077 mappába, majd indítsd újra a játékot.",
    ["The conversation service did not answer the setup check, so its Runtime is probably older than these Scripts. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "A beszélgetési szolgáltatás nem válaszolt a telepítés-ellenőrzésre, ezért a Runtime-ja valószínűleg régebbi, mint ezek a Scripts. Csomagold ki a teljes telepítő zip-et (AI-NPC-LLM-Companions, a Nexus Mods oldalán) a Cyberpunk 2077 mappába, majd indítsd újra a játékot.",
    ["The Runtime update from {from} to {to} was never applied, so some Runtime files are old. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "A Runtime {from} verzióról {to} verzióra szóló frissítése sosem lett alkalmazva, ezért a Runtime egyes fájljai régiek. Csomagold ki a teljes telepítő zip-et (AI-NPC-LLM-Companions, a Nexus Mods oldalán) a Cyberpunk 2077 mappába, majd indítsd újra a játékot.",
    ["Runtime files are old. Get the full install zip."] = "A Runtime fájlok régiek. Töltsd le a teljes ZIP-et.",
    ["Character unavailable in this game installation."] = "A karakter nem elérhető ebben a játéktelepítésben.",
    ["Message could not be delivered. Please try again."] = "Az üzenetet nem sikerült kézbesíteni. Próbáld újra.",
    ["The conversation service could not reply. Please try again."] = "A beszélgetési szolgáltatás nem tudott válaszolni. Próbáld újra.",
    ["Voice conversation failed. Check your microphone and try again."] = "Hangbeszélgetés sikertelen. Ellenőrizd a mikrofont, majd próbáld újra.",
    ["Companions now and then pause, hesitate, laugh or sigh, as their personality would. It stays rare.\n\nOmniVoice can voice laughs and sighs; the other voices only add pauses.\n\nNot available with Convai’s cloud voice: choosing it turns this off, and turning this on switches the voice to Pocket."] = "A társak időnként szünetet tartanak, habozhatnak, nevethetnek vagy sóhajthatnak, a személyiségüknek megfelelően. Ez ritka marad.\n\nAz OmniVoice tud nevetést és sóhajt megszólaltatni; a többi hang csak szüneteket ad hozzá.\n\nNem elérhető a Convai felhőhangjával: ennek kiválasztása kikapcsolja ezt, a bekapcsolása pedig a hangot Pocketre váltja.",
    ["For testing and bug reports; leave it off for normal play.\n\nShows routine popups, writes a movement trace in the mod’s runtime folder, logs gesture decisions and adds itself to support reports.\n\nFailures, preparation progress and joined notices stay visible when it is off."] = "Teszteléshez és hibajelentéshez; normál játéknál hagyd kikapcsolva.\n\nMegjeleníti a rutin felugró ablakokat, mozgásnaplót ír a mod futásidejű mappájába, naplózza a gesztusdöntéseket, és bekerül a támogatási jelentésekbe.\n\nA hibák, a felkészítés előrehaladása és a csatlakozási értesítések kikapcsolt állapotban is láthatók maradnak.",
    ["Pocket: the lightest, on your CPU, about 0.2 s to the first word.\n\nOmniVoice: richer, needs a capable GPU and its pack, 1 to 2.5 s.\n\nVoxtral: cloud voices with your Mistral key. The companions’ voice loads no local model; V’s typed lines follow V’s own voice setting.\n\nConvai: its own cloud voice. A voice that cannot run shows replies as text."] = "Pocket: a legkönnyebb, a processzoron fut, az első szó kb. 0,2 mp alatt.\n\nOmniVoice: gazdagabb, erős GPU és a csomagja kell hozzá, 1–2,5 mp.\n\nVoxtral: felhőbeli hangok a saját Mistral-kulcsoddal. A társak hangja nem tölt be helyi hangmodellt; V begépelt sorai V saját hangbeállítását követik.\n\nConvai: saját felhőhangja. A nem futtatható hangnál a válaszok szövegként jelennek meg.",
    ["The game’s own named characters, such as Judy, Jackie, Panam and Rogue, answer when you talk to them where they stand, with their own voice and memory.\n\nNothing else about them changes: they do not turn, move, gesture or follow, and stay quiet during scenes, quest conversations, fights and rides.\n\nTakes effect after you reload your save."] = "A játék saját, nevesített karakterei, mint Judy, Jackie, Panam és Rogue, ott válaszolnak, ahol állnak, amikor megszólítod őket, saját hangjukkal és emlékezetükkel.\n\nMásban nem változnak: nem fordulnak meg, nem mozognak, nem gesztikulálnak és nem követnek. Jelenetek, küldetésbeszélgetések, harcok és utazások alatt hallgatnak.\n\nA mentés újratöltése után lép életbe.",
    ["Mod Organizer 2. Files the mod creates go to its Overwrite folder; leave them there. Install the full install zip as one mod and update that mod with each new full install zip. Extract multilingual packs into that mod’s folder, not as new mods. Mention Mod Organizer 2 when you send a report."] = "Mod Organizer 2. A mod által létrehozott fájlok az Overwrite mappájába kerülnek; hagyd őket ott. A teljes telepítő zip-et egy modként telepítsd, és minden új teljes telepítő zip-pel frissítsd ezt a modot. A többnyelvű csomagokat ennek a modnak a mappájába csomagold ki, ne új modokként. Jelentés küldésekor említsd meg a Mod Organizer 2-t.",
    ["With a mod manager: remove the old Scripts and Runtime mods, then install the full install zip as one mod."] = "Modkezelővel: töröld a régi Scripts és Runtime modokat, majd telepítsd a teljes telepítő zip-et egy modként.",
    ["When something in the mod goes wrong, a short report goes to the developer.\n\nIt never holds keys, what you or the characters say, memories, audio or your Windows user name.\n\nIt holds the error, versions, settings, PC details (graphics card, processor, Windows, security software, drive, screen), mod names, setup check, reply timings and nearby log lines (for setup and script errors also the Cyber Engine Tweaks log)."] = "Hiba esetén rövid jelentés megy a fejlesztőnek.\n\nSoha nem tartalmaz kulcsokat, beszélgetéseket, emlékeket, hangot vagy a Windows-felhasználóneved.\n\nTartalmazza a hibát, a verziókat, a beállításokat, géped adatait (videókártya, processzor, Windows, biztonság, meghajtó, képernyő), a modokat, telepítés-ellenőrzést, válaszidőket és közeli naplósorokat (telepítési és szkripthibáknál a Cyber Engine Tweaks naplóját is).",
    ["Some Runtime files are from a newer update than this Runtime says. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder again. Then restart the game."] = "Néhány Runtime-fájl újabb frissítésből származik, mint amit ez a Runtime jelez. Csomagold ki újra a teljes telepítő zip-et (AI-NPC-LLM-Companions, a Nexus Mods oldalán) a Cyberpunk 2077 mappába. Utána indítsd újra a játékot.",
    ["Multilingual pack ({code})"] = "Többnyelvű csomag ({code})",
    ["PocketTTS model ({code})"] = "PocketTTS modell ({code})",
    ["Your typed lines are spoken out loud too, in the V voice that matches yours, then the companion answers. V’s line is always waited for, up to about 30 s without audio.\n\nPocket: on your processor, about 0.2 s (its own small model if the companions use another voice). Voxtral: cloud, with your Mistral key. OmniVoice: the companions’ GPU voice, a second more wait."] = "A begépelt sorokat V is kimondja hangosan, a hozzád illő V-hangon, utána válaszol a társ. V sorát mindig megvárjuk, legfeljebb kb. 30 mp-ig hang nélkül.\n\nPocket: a processzoron, kb. 0,2 mp alatt indul (saját kis modellt tölt be, ha a társak más hangot használnak). Voxtral: a felhőben, a Mistral-kulcsoddal. OmniVoice: a társak GPU-hangja, egy másodperccel több várakozás.",
    ["Custom: {model} at {host}"] = "Egyéni: {model} ({host})",
    ["Mistral"] = "Mistral",
    ["Local AI, Lite"] = "Local AI, Lite",
    ["Local AI, Standard"] = "Local AI, Standard",
    ["Local AI, Lite, Mature on"] = "Local AI, Lite, felnőtt tartalom",
    ["Local AI, Standard, Mature on"] = "Local AI, Standard, felnőtt tartalom",
    ["Heading of the output rules"] = "A kimeneti szabályok címsora",
