    ["{name} now has the characters of your party."] = "{name} most már a csapatod karaktereit tartalmazza.",
    ["{party}: inviting {names}."] = "{party}: {names} meghívása folyamatban.",
    ["Adds {name} to your favorites. They are listed at the top of page 1, and first in the phone’s Chat tab. Updates never touch them."] = "{name} bekerül a kedvencek közé. Az 1. oldal tetején és a telefon Chat fülén elsőként láthatók. A frissítések soha nem nyúlnak hozzájuk.",
    ["Favorites"] = "Kedvencek",
    ["Only the first {count} favorites are listed here. The others are in the list below."] = "Itt csak az első {count} kedvenc látszik. A többi az alábbi listában található.",
    ["Page {page} of {pages}: {kind} {first} to {last}."] = "Oldal {page} / {pages}: {kind} {first}–{last}.",
    ["Press to go to page {page} of {pages}: {kind} {first} to {last}."] = "Nyomja meg az ugráshoz: oldal {page} / {pages}: {kind} {first}–{last}.",
    ["Takes {name} out of your favorites. Her place in the list below stays."] = "{name} kikerül a kedvencek közül. Helye az alábbi listában megmarad.",
    ["This is the first page."] = "Ez az első oldal.",
