    ["models"] = "modellek",
    ["{count} more favorites"] = "Még {count} kedvenc",
    ["{name} is now a favorite. Favorites are at the top of page 1."] = "{name} mostantól a kedvencek közé tartozik. A kedvencek az 1. oldal tetején állnak.",
