    ["Pyjamas"] = "Pizsama",
    ["Go back to the usual look and moves for {name}? Your choices on this part are removed."] = "Visszaállítja {name} szokásos kinézetét és mozgását? Az e részhez tartozó választások törlődnek.",
    ["Back to the usual look and moves."] = "Vissza a szokásos kinézethez és mozgáshoz.",
    ["Choices for how this character looks and moves. They work with every conversation option, Convai included, except the reply length."] = "A karakter kinézetének és mozgásának beállításai. Minden beszélgetési lehetőséggel működnek, a Convai-val együtt is, a válaszhossz kivételével.",
    ["Outfit"] = "Öltözet",
    ["Automatic follows the “Companions change outfits” setting in the game: day and night looks, now and then a change, and casual clothes at home. A look you pick is worn all the time. Only your own companions and residents are dressed, and they change while nobody is looking. Characters the game places are never changed."] = "Az Automatikus a játékban lévő „Társak ruhát váltanak” beállítást követi: nappali és éjszakai kinézetek, időnként egy váltás, és otthon hétköznapi ruha. A kiválasztott kinézetet folyamatosan viselik. Csak a saját társak és lakók öltöznek át, és váltanak, amikor senki nem figyeli őket. A játék által elhelyezett karakterek soha nem változnak.",
    ["This character has only one look in the game files, so there is no outfit to choose."] = "Ennek a karakternek a játékfájlokban csak egy kinézete van, ezért nincs választható öltözet.",
    ["Talking gestures"] = "Beszédközbeni gesztusok",
    ["How the hands move while they speak a longer reply."] = "Hogyan mozognak a kezek, amikor hosszabb választ mondanak.",
    ["Normal"] = "Normál",
    ["Calm: smaller gestures, not as often"] = "Nyugodt: kisebb gesztusok, nem annyira gyakran",
    ["Lively: bigger gestures, more often"] = "Élénk: nagyobb gesztusok, gyakrabban",
    ["None: the hands stay at rest"] = "Nincs: a kezek nyugalomban maradnak",
    ["Nod while you talk to them"] = "Bólintás a beszélgetés közben",
    ["A small nod now and then while you speak."] = "Időnként egy kis bólintás beszéd közben.",
    ["Idle moves"] = "Tétlen mozgások",
    ["What they do now and then while they stand beside you."] = "Amit időnként tesznek, miközben a közelben állnak.",
    ["Plain stances only, no props like a cup or a cigarette"] = "Csak egyszerű testtartások, tárgyak, például csésze vagy cigaretta nélkül",
    ["None: they keep the stance they have"] = "Nincs: megtartják a jelenlegi testtartásukat",
    ["Sit down and take a place"] = "Leülni és helyet foglalni",
    ["Takes a seat beside you when you sit, and a seat or a spot in your flat at home. Switched off, they stay on their feet beside you."] = "Leüléskor a mellé ül, otthon a lakásban pedig ülőhelyet vagy helyet foglal el. Kikapcsolva állva maradnak a közelben.",
    ["Comment on fights and loot"] = "Harcok és zsákmány kommentálása",
    ["Switched off, they say nothing about fights or about what you pick up."] = "Kikapcsolva nem mondanak semmit a harcokról és a felvett tárgyakról.",
    ["Reply length"] = "Válaszhossz",
    ["Shorter: up to about {words} words"] = "Rövidebb: legfeljebb kb. {words} szó",
    ["Very short: up to about {words} words"] = "Nagyon rövid: legfeljebb kb. {words} szó",
    ["A saved choice counts within a few seconds. Clothes change when nobody is looking."] = "A mentett választás néhány másodpercen belül érvényesül. A ruha akkor cserélődik, amikor senki nem figyeli.",
    ["Look and moves"] = "Kinézet és mozgás",
    ["Shift"] = "Shift",
    ["Ctrl"] = "Ctrl",
    ["Alt"] = "Alt",
    ["Hold Shift, Ctrl or Alt while you press a key to set a combination such as Shift+F5. A combination runs only with exactly those keys held, and a plain key does not run while one is held. In the game Shift sprints, Ctrl dodges and Alt opens the weapon wheel, so V does that too."] = "Tartsd lenyomva a Shift, Ctrl vagy Alt billentyűt, miközben megnyomsz egy billentyűt, így kombinációt állítasz be, például Shift+F5. A kombináció csak pontosan ezekkel a lenyomott billentyűkkel fut le, az egyszerű billentyű pedig nem fut le, amíg valamelyik le van nyomva. A játékban a Shift sprintel, a Ctrl kitér, az Alt pedig megnyitja a fegyverkereket, így V is ezt teszi.",
    ["Disk space"] = "Lemezterület",
    ["Your {drive} drive is almost full ({free} GB free). Free space so the mod can save logs and memories."] = "A {drive} meghajtód majdnem tele ({free} GB szabad). Adj helyet, hogy a mod menthesse naplóit és emlékeit.",
    ["An input marked (!) looks like a loopback or virtual input, such as Stereo Mix, CABLE Output or a mixer’s Out. It can carry other apps’ sound, for example the far side of a call, so the mod never picks one by itself."] = "A (!) jelölésű bemenet loopback vagy virtuális bemenetnek látszik, például Stereo Mix, CABLE Output vagy egy mixer kimenete. Más alkalmazások hangját is továbbíthatja, például egy hívás másik oldalát, ezért a mod soha nem választ ki egyet magától.",
    ["The input you chose looks like it carries PC sound, not only your voice. If characters hear your calls, choose your real microphone."] = "A kiválasztott bemenet úgy tűnik, hogy a számítógép hangját is továbbítja, nem csak a hangodat. Ha a karakterek hallják a hívásaidat, válaszd a valódi mikrofonodat.",
    ["{name} looks like it carries PC sound, such as a call, not only your voice. Choose your real microphone in Settings > Voices > Microphone."] = "{name} úgy tűnik, hogy a számítógép hangját is továbbítja, például egy hívást, nem csak a hangodat. Válaszd a valódi mikrofonodat a Beállítások > Hangok > Mikrofon menüben.",
    ["Companions can see"] = "A társak látnak",
    ["Each line also gets a recent picture of your surroundings, taken from the game window just before you talk. Works with every conversation provider. Local AI needs a model that can see. A model that cannot just gets your words.\n\nOnly the game window, only while someone is near, kept briefly in memory. Off means nothing is captured."] = "Minden sorhoz kap egy friss képet is a környezetedről a játékablakból. Minden beszélgetési szolgáltatóval működik. A Local AI-hoz olyan modell kell, amely lát. Ha nem lát, csak a szavaidat kapja.\n\nCsak a játékablak, csak ha valaki a közelben van, rövid ideig a memóriában marad. Kikapcsolva semmi nem kerül rögzítésre.",
    ["The yellow border is Windows showing a capture. Turn off Companions can see to stop it."] = "A sárga keret a Windows felvételét jelzi. Leállításhoz kapcsold ki: A társak látnak.",
    ["This Local AI model cannot see pictures, so replies use only your words."] = "Ez a Local AI modell nem lát képeket, ezért csak a szavaidat kapja.",
    ["This model can see pictures with its vision file, from {folder}/vision on Hugging Face."] = "Ez a modell a Hugging Face {folder}/vision mappájában lévő vision fájllal lát képeket.",
    ["Your Custom endpoint does not accept pictures, so replies use only your words."] = "A Custom végpontod nem fogad képeket, ezért csak a szavaidat kapja.",
    ["No API key is saved yet. Copy your key from your provider, press Paste API key, then test again."] = "Még nincs mentett API-kulcs. Másold ki a kulcsodat a szolgáltatódtól, nyomd meg a Kulcs beillesztése gombot, majd teszteld újra.",
    ["Add"] = "Hozzáadás",
    ["Deletes this free setup: the endpoint URL, the model ID and the API key saved with it."] = "Törli ezt az ingyenes beállítást: az endpoint URL-t, a modell-azonosítót és a vele mentett kulcsot.",
    ["Allow Local AI to use RAM"] = "Local AI: RAM használata",
    ["Off: when the Local AI model you chose does not fit the free graphics memory beside the game, a smaller model that fits is loaded instead, with one notice.\n\nOn: your chosen model is kept and part of it runs from system memory (RAM) on the processor. Replies are slower, and you are told once. It needs enough free RAM, and the game may have less processor time."] = "Ki: ha a kiválasztott Local AI modell nem fér el a játék mellett a szabad videomemóriában, helyette egy kisebb, beférő modell töltődik be, egyetlen értesítéssel.\n\nBe: a kiválasztott modell megmarad, és egy része a rendszermemóriából (RAM) fut a processzoron. A válaszok lassabbak lesznek, és erről egyszer értesítünk. Elég szabad RAM kell hozzá, és a játék kevesebb processzoridőt kaphat.",
    ["Using {model}"] = "{model} használatban",
    ["{model} is in use because the model you chose did not fit beside the game. Your choice is unchanged."] = "A {model} modellt használjuk, mert a kiválasztott modell nem fért el a játék mellett. A választásod nem változik.",
    ["Local AI is keeping {model} as you allowed, with part of it in system memory. Replies will be slower."] = "A Local AI a engedélyed szerint megtartja a {model} modellt, egy részét a rendszermemóriában tartja. A válaszok lassabbak lesznek.",
    ["Choosing Convai or Google Gemini turns it off. Voxtral is not used with it: a voice on Voxtral moves to Pocket and comes back when it is turned off."] = "A Convai vagy a Google Gemini kiválasztása ezt kikapcsolja. Ezzel nem használják a Voxtralt: a Voxtral hangja Pocketre vált, és kikapcsoláskor visszatér.",
    ["Convai could not sign in. Try again in a moment, or choose Google Gemini or Local AI in Settings > Conversation provider."] = "Nem sikerült bejelentkezni a Convai-ba. Próbáld újra kis idő múlva, vagy a Beállítások > Beszélgetési szolgáltató menüpontban válaszd a Google Geminit vagy a Local AI-t.",
    ["Convai is answering right now, so these changes have no effect yet. Choose Google Gemini, Local AI or Custom as the conversation provider in the settings."] = "A Convai most válaszol, ezért ezek a módosítások még nem hatnak. A beállításokban válaszd a Google Gemini, a Local AI vagy az Egyéni beszélgetési szolgáltatót.",
    ["Convai: Google Gemini has no key yet"] = "Convai: nincs még Google Gemini-kulcs",
    ["Copy your Mistral API key first, then press Add. It fills in the endpoint URL and the model ID for Mistral (Ministral 8B) and saves your key from the clipboard. The same key powers the Voxtral cloud voice.\n\nNew Mistral accounts may not get a free API key any more."] = "Másold ki először a Mistral API-kulcsodat, majd nyomd meg az Add gombot. Kitölti az endpoint URL-jét és a modell-azonosítót a Mistral (Ministral 8B) számára, és elmenti a kulcsodat a vágólapról. Ugyanez a kulcs működteti a Voxtral felhőhangot.\n\nAz új Mistral-fiókok lehet, hogy már nem kapnak ingyenes API-kulcsot.",
    ["Copy your key from Google AI Studio first (aistudio.google.com/apikey, a Google account is enough, no card). It is read from the clipboard once and saved on this computer.\n\nThe free plan has a daily limit of about 1,000 replies, is not offered in every country, and Google may use free-plan chats to improve its products."] = "Másold ki először a kulcsodat a Google AI Studio oldaláról (aistudio.google.com/apikey, elég hozzá egy Google-fiók, kártya nem kell). A vágólapról egyszer olvassa be, és ezen a számítógépen tárolja.\n\nAz ingyenes csomagnak napi körülbelül 1000 válaszos korlátja van, nem minden országban érhető el, a Google pedig felhasználhatja az ingyenes csomagban folytatott beszélgetéseidet a termékei fejlesztésére.",
    ["Edit a character’s bio, speaking style, speaking rules and memories, and the prompting for each AI option, or make a character of your own, in your browser.\n\nWorks with Google Gemini, Local AI and Custom, not Convai. Changes apply from the next reply."] = "Szerkeszd a karakter életrajzát, beszédstílusát, beszédszabályait és emlékeit, valamint az egyes AI-lehetőségek promptját, vagy készíts saját karaktert a böngésződben.\n\nGoogle Gemini, Local AI és Egyéni mellett működik, Convai mellett nem. A módosítások a következő választól érvényesek.",
    ["Edit characters’ bios, rules and memories, and the prompting for each AI option, in your browser.\n\nWorks with Google Gemini, Local AI and Custom, not Convai. Changes apply from the next reply."] = "Szerkeszd a böngésződben a karakterek életrajzát, szabályait és emlékeit, valamint az egyes AI-lehetőségek promptját.\n\nGoogle Gemini, Local AI és Egyéni mellett működik, Convai mellett nem. A módosítások a következő választól érvényesek.",
    ["From Convai or Google Gemini, turning it on selects Local AI, or Custom when Local AI is not installed. With Local AI it also selects the largest uncensored model that fits. Turning it off restores your choices."] = "Convai vagy Google Gemini mellett a bekapcsolás a Local AI-t választja, vagy az Egyénit, ha a Local AI nincs telepítve. Local AI mellett a legnagyobb, ráférő cenzúrázatlan modellt is kiválasztja. Kikapcsolásakor visszaállnak a választásaid.",
    ["Google Gemini (free plan)"] = "Google Gemini (ingyenes)",
    ["Google Gemini API key"] = "Google Gemini API-kulcs",
    ["Google Gemini has no key yet, so Convai is used. Add your key in Settings > Conversation provider."] = "A Google Gemini-hoz még nincs kulcs, ezért a Convai van használatban. Add meg a kulcsodat a Beállítások > Beszélgetési szolgáltató menüpontban.",
    ["Google Gemini replies are spoken by a local voice instead of the Convai cloud voice."] = "A Google Gemini válaszait helyi hang mondja fel, nem a Convai felhős hangja.",
    ["Google Gemini: key not accepted"] = "Google Gemini: a kulcs nem elfogadott",
    ["Google Gemini: limit reached for now"] = "Google Gemini: a keret egyelőre betelt",
    ["Google Gemini: model unavailable"] = "Google Gemini: a modell nem érhető el",
    ["Mistral (your key)"] = "Mistral (kulcsod)",
    ["Requires a Mistral key (add it with the Mistral preset on the Custom endpoint page)"] = "Mistral-kulcs szükséges (add hozzá a Mistral-előbeállítással a Custom endpoint oldalon)",
    ["The conversation limit has been reached. Try again later, or choose Local AI or Google Gemini in Settings > Conversation provider."] = "Elérted a beszélgetési keretet. Próbáld újra később, vagy a Beállítások > Beszélgetési szolgáltató menüpontban válaszd a Local AI-t vagy a Google Geminit.",
    ["The longest reply, in words. Works with Google Gemini, Local AI and Custom, not Convai."] = "A leghosszabb válasz szavakban. Google Gemini, Local AI és Custom esetén működik, Convai esetén nem.",
    ["They join as a copy of the model they were made from. They talk with Google Gemini, Local AI or Custom; with Convai they talk as an ordinary person."] = "Annak a modellnek a másolataként csatlakozik, amelyből készült. Google Gemini, Local AI vagy Egyéni segítségével beszél; Convai mellett hétköznapi emberként beszél.",
    ["Today’s Convai turns are used.\nIt resets at {time}. Try Local AI (unlimited) or Google Gemini (your own key)."] = "Elfogytak a mai Convai-körök.\nVisszaáll {time}-kor. Local AI (korlátlan) vagy Google Gemini (saját kulcs).",
    ["Today’s Convai turns are used.\nTry Local AI (unlimited) or Google Gemini (your own key)."] = "Elfogytak a mai Convai-körök.\nLocal AI (korlátlan) vagy Google Gemini (saját kulcs).",
    ["Today’s {limit} Convai turns are used.\nIt resets at {time}. Try Local AI (unlimited) or Google Gemini (your own key)."] = "Elfogyott a mai {limit} Convai-kör.\nVisszaáll {time}-kor. Local AI (korlátlan) vagy Google Gemini (saját kulcs).",
    ["Today’s {limit} Convai turns are used.\nTry Local AI (unlimited) or Google Gemini (your own key)."] = "Elfogyott a mai {limit} Convai-kör.\nLocal AI (korlátlan) vagy Google Gemini (saját kulcs).",
    ["Turns the content pack {name} on or off. A pack changes how the characters talk. Its prompt changes work with Google Gemini, Local AI and Custom. On Convai its world rules and its own Convai characters apply. A switch counts from the next reply, new names after a restart."] = "Be- vagy kikapcsolja a(z) {name} tartalomcsomagot. A csomag megváltoztatja, hogyan beszélnek a karakterek. A promptmódosításai működnek Google Gemini, Local AI és Egyéni esetén. Convai esetén érvényesek a csomag világszabályai és saját Convai-karakterei. A kapcsolás a következő választól számít, az új nevek újraindítás után.",
    ["What the game tells each character about this moment. A character mentions it only when it fits the talk.\n\nAn off kind is left out of every conversation provider (Convai, Google Gemini, Local AI and Custom)."] = "Azt, amit a játék ebben a pillanatban elmond minden karakternek. A karakter csak akkor említi, ha illik a beszélgetésbe.\n\nA kikapcsolt elemek kimaradnak minden beszélgetési szolgáltatónál (Convai, Google Gemini, Local AI és Egyéni).",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key. Google Gemini uses your own free key, and its memory stays on this computer.\n\nWith Google Gemini, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works."] = "Ki írja a társaid válaszait. A változtatás addig vár, amíg nem fut beszélgetés.\n\nA Convai ingyenes szintje nem igényel beállítást, és jobb válaszokat ad. A Convai API-kulcs a saját kulcsodat használja. A Google Gemini a saját ingyenes kulcsodat használja, a memória pedig ezen a számítógépen marad.\n\nGoogle Gemini, Local AI vagy Egyéni esetén a Convai felhőhangját helyi hang váltja. A beszédfelismerés ezen a számítógépen történik, így a hangbillentyű működik.",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key. Google Gemini uses your own free key, and its memory stays on this computer.\n\nWith Google Gemini, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with them, so type your messages."] = "Ki írja a társaid válaszait. A változtatás addig vár, amíg nem fut beszélgetés.\n\nA Convai ingyenes szintje nem igényel beállítást, és jobb válaszokat ad. A Convai API-kulcs a saját kulcsodat használja. A Google Gemini a saját ingyenes kulcsodat használja, a memória pedig ezen a számítógépen marad.\n\nGoogle Gemini, Local AI vagy Egyéni esetén a Convai felhőhangját helyi hang váltja. A hangbillentyűhöz szükséges beszédfelismerés még nem érhető el velük, ezért írd be az üzeneteidet.",
    ["You have used today’s {limit} turns, which come back at {time}. To keep talking now, choose Local AI (unlimited) or Google Gemini (with your own key)."] = "Ma már felhasználtad a {limit} fordulódat. {time}-kor újra elérhetők. A folytatáshoz válaszd a Local AI-t (nincs korlát) vagy a Google Geminit (saját kulccsal).",
    ["You have used today’s {limit} turns, which come back tomorrow. To keep talking now, choose Local AI (unlimited) or Google Gemini (with your own key)."] = "Ma már felhasználtad a {limit} fordulódat. Holnap újra elérhetők. A folytatáshoz válaszd a Local AI-t (nincs korlát) vagy a Google Geminit (saját kulccsal).",
    ["Your changes work with Google Gemini, Local AI and Custom. They do not apply to Convai."] = "A módosításaid Google Gemini, Local AI és Egyéni mellett működnek. Convai esetén nem érvényesek.",
    ["Your own characters talk only with Google Gemini, Local AI or Custom. With Convai they speak as an ordinary person."] = "Saját karaktereid csak Google Gemini, Local AI vagy Egyéni mellett beszélnek. Convai mellett hétköznapi emberként beszélnek.",
    ["{name} is one of your own characters. They need Google Gemini, Local AI or Custom, so with Convai they talk as an ordinary person."] = "{name} az egyik saját karaktered. Google Gemini, Local AI vagy Egyéni kell neki, ezért Convai mellett hétköznapi emberként beszél.",
    ["{name} is one of your own characters. They need Google Gemini, Local AI or Custom: choose one under Conversation provider in the settings."] = "{name} az egyik saját karaktered. Google Gemini, Local AI vagy Custom szolgáltatóra van szüksége: válassz egyet a beállításokban, a „Beszélgetési szolgáltató” alatt.",
    ["This character needs Google Gemini, Local AI or Custom to answer."] = "Ennek a karakternek Google Gemini, Local AI vagy Egyéni szolgáltatóra van szüksége a válaszhoz.",
    ["You’ve reached today’s Convai free tier limit. It resets at {time}. To keep talking now, choose another provider in Settings > Conversation provider. Local AI is unlimited and runs on your PC. Google Gemini works with your own key."] = "Elérted a mai Convai (ingyenes szint) keretét. Visszaáll {time}-kor. Hogy most is folytathasd, válassz másik szolgáltatót a Beállítások > Beszélgetési szolgáltató menüpontban. A Local AI korlátlan, és a számítógépeden fut. A Google Gemini a saját kulcsoddal működik.",
    ["You’ve reached today’s Convai free tier limit. It resets tomorrow. To keep talking now, choose another provider in Settings > Conversation provider. Local AI is unlimited and runs on your PC. Google Gemini works with your own key."] = "Elérted a mai Convai (ingyenes szint) keretét. Holnap újra elérhető. Hogy most is folytathasd, válassz másik szolgáltatót a Beállítások > Beszélgetési szolgáltató menüpontban. A Local AI korlátlan, és a számítógépeden fut. A Google Gemini a saját kulcsoddal működik.",
    ["Character bonds"] = "Kötelékek a karakterekkel",
    ["Every named character has a bond with you, level 1 to 10. Quests finished together, a romance, eddies paid back and talking raise it; threats and insults lower it. Closer characters trust you more.\n\nA notice shows each level change. Forget clears the talk part. Off by default."] = "Minden karakterhez kötelék fűz, 1-es és 10-es szint között. Nő a közösen teljesített küldetésekkel, egy románccal, a visszafizetett eddies-szel és a beszélgetéssel; a fenyegetések és sértések csökkentik. A közelebbi karakterek jobban megbíznak benned.\n\nÉrtesítés jelzi minden szintváltozást. Az Elfelejtés törli a beszélgetést. Alapból kikapcsolva.",
    ["Bond with {name}: level {level}, {title}"] = "{name} kötelék: {level}. szint, {title}",
    ["Bond with {name} fell: level {level}, {title}"] = "{name} kötelék csökkent: {level}. szint, {title}",
    ["Acquaintance"] = "Ismerős",
    ["Familiar face"] = "Ismerős arc",
    ["Friendly"] = "Barátságos",
    ["Friend"] = "Barát",
    ["Good friend"] = "Jó barát",
    ["Close friend"] = "Közeli barát",
    ["Trusted"] = "Megbízható",
    ["Confidant"] = "Bizalmas",
    ["Family"] = "Család",
    ["Ride or die"] = "Halálig hű",
    ["Story packs"] = "Történetcsomagok",
    ["When you are close and a character’s own quests are done, they can start a short story of their own. It plays out in talks, texts and calls, and some use Eddies with characters and Immersive invitations.\n\nNeeds Character bonds. Own characters and channels only, never the game’s own scenes or quests. Off by default."] = "Ha közel vagy egy karakterhez, és a saját küldetései véget értek, elindíthat egy rövid saját történetet. A beszélgetésekben, üzenetekben és hívásokban zajlik, néhány használja az Eddies a karakterekkel és a Magával ragadó meghívókat.\n\nKötelékek a karakterekkel szükséges. Csak a saját karaktereid és csatornáid, soha a játék jelenetei vagy küldetései. Alapból kikapcsolva.",
    ["Characters text first"] = "A karakterek írnak először",
    ["Characters you are close to can text or call you first now and then, and Johnny can speak up in your head. It only happens at calm moments, never in a fight, a scene or a call, and only a few times a day.\n\nNeeds Story packs. Own characters and channels only. On by default."] = "A karakterek, akikhez közel állsz, időnként először írhatnak vagy hívhatnak téged, Johnny pedig megszólalhat a fejedben. Ez csak nyugodt pillanatokban történik, soha harc, jelenet vagy hívás közben, és naponta csak néhányszor.\n\nTörténetcsomagok szükséges. Csak a saját karaktereid és csatornáid. Alapból bekapcsolva.",
    ["Bond: level {level}, {title}"] = "Kötelék: {level}. szint, {title}",
    ["Story: {title}"] = "Történet: {title}",
    ["Bonds are not kept while Character bonds is off, so nobody is listed here. Turn it on in Settings, under Gameplay."] = "A kötelékeket nem tartja nyilván a játék, amíg a Kötelékek a karakterekkel ki van kapcsolva, ezért itt senki sincs. Kapcsold be a Beállítások Játékmenet részében.",
    ["Character bonds are off"] = "A Kötelékek a karakterekkel ki van kapcsolva",
    ["From their story: {story}, from talking: {talk}"] = "A történetükből: {story}, a beszélgetésekből: {talk}",
    ["Highest level"] = "Legmagasabb szint",
    ["Hurt: {points}"] = "Megbántva: {points}",
    ["Hurt: {points}, gone in about a game day"] = "Megbántva: {points}, nagyjából egy játéknap múlva elmúlik",
    ["Hurt: {points}, gone in about {days} game days"] = "Megbántva: {points}, nagyjából {days} játéknap múlva elmúlik",
    ["Last talked: today"] = "Utoljára beszéltetek: ma",
    ["Last talked: yesterday"] = "Utoljára beszéltetek: tegnap",
    ["Last talked: {days} days ago"] = "Utoljára beszéltetek: {days} napja",
    ["Level {level}"] = "{level}. szint",
    ["No story yet"] = "Még nincs történet",
    ["Nobody yet"] = "Még senki",
    ["See the characters you have talked to and how close each one is to you: the bond level, what raised or hurt it, their quests and the stories they are in."] = "Nézd meg, kikkel beszéltél, és mennyire állnak közel hozzád: a kötelék szintjét, mi emelte vagy rontotta, a küldetéseiket és a történeteiket.",
    ["Talk to a character and your bond with them shows here."] = "Beszélj egy karakterrel, és a vele való köteléked itt jelenik meg.",
    ["The characters you have talked to and how close each one is to you. The most recent come first."] = "Akikkel beszéltél, és mennyire állnak közel hozzád. A legfrissebbek vannak elöl.",
    ["Their quests: {done} of {total} finished"] = "Küldetéseik: {done} / {total} teljesítve",
    ["Warmth: {points}"] = "Melegség: {points}",
    ["{points} of {needed} points to level {to}"] = "{points} / {needed} pont a(z) {to}. szintig",
